//! Security descriptors, SIDs and token privileges.
//!
//! A descriptor Windows hands back is a single `LocalAlloc` block whose inner
//! pointers (owner, DACL, ACEs, SIDs) all point inside it. The types in the
//! `acl` submodule turn that block into bounds-checked byte views before
//! anything is read, so a malformed or hostile descriptor is rejected by
//! offset arithmetic rather than dereferenced.
#![allow(unsafe_code)]

mod acl;

use std::ffi::c_void;
use std::io;
use std::marker::PhantomData;
use std::mem::size_of;
use std::os::windows::io::{AsHandle, AsRawHandle, OwnedHandle};
use std::path::Path;
use std::ptr::{self, NonNull};

use windows_sys::Win32::Foundation::{
    LocalFree, SetLastError, ERROR_INSUFFICIENT_BUFFER, ERROR_NOT_ALL_ASSIGNED, ERROR_SUCCESS, LUID,
};
use windows_sys::Win32::Security::Authorization::{
    ConvertSidToStringSidW, ConvertStringSecurityDescriptorToSecurityDescriptorW,
    GetNamedSecurityInfoW, GetSecurityInfo, TreeSetNamedSecurityInfoW, SDDL_REVISION_1,
    SE_FILE_OBJECT, SE_KERNEL_OBJECT, TREE_SEC_INFO_RESET,
};
use windows_sys::Win32::Security::{
    AdjustTokenPrivileges, CheckTokenMembership, GetSecurityDescriptorControl,
    GetSecurityDescriptorDacl, GetSecurityDescriptorLength, GetSecurityDescriptorOwner,
    GetTokenInformation, LookupPrivilegeValueW, TokenUser, DACL_SECURITY_INFORMATION,
    LUID_AND_ATTRIBUTES, OWNER_SECURITY_INFORMATION, PROTECTED_DACL_SECURITY_INFORMATION,
    PSECURITY_DESCRIPTOR, SECURITY_ATTRIBUTES, SE_PRIVILEGE_ENABLED, TOKEN_ADJUST_PRIVILEGES,
    TOKEN_PRIVILEGES, TOKEN_QUERY, TOKEN_USER,
};
use windows_sys::Win32::System::Threading::OpenProcessToken;

pub use acl::{
    AclValidationError, AllowedAce, OwnedSid, SecurityAclError, ValidatedDacl, ValidatedSid,
};

use crate::bounded_read::{probe_word_aligned, CallOutcome};
use crate::handle::{current_process, owned_from_creation};
use crate::wide::{bounded_units, wide_null};

const MAX_TOKEN_INFORMATION_BYTES: usize = 64 * 1024;
const MAX_SID_STRING_UNITS: usize = 32_768;

/// A security descriptor built from SDDL, for creating objects
/// ([`crate::PipeServer`], [`crate::NamedMutex`], [`crate::Job`]) and for
/// resetting the ACLs of a directory tree.
///
/// ```no_run
/// # fn main() -> std::io::Result<()> {
/// use win_custody::SecurityDescriptor;
///
/// // LocalSystem and the built-in Administrators get full access; nobody
/// // else gets any, and the DACL does not inherit from its parent.
/// let descriptor = SecurityDescriptor::from_sddl("D:P(A;;GA;;;SY)(A;;GA;;;BA)")?;
/// # Ok(())
/// # }
/// ```
#[derive(Debug)]
pub struct SecurityDescriptor(NonNull<c_void>);

// SAFETY: the descriptor is an immutable LocalAlloc block owned by this value;
// Windows only reads it, so it may be moved to and shared between threads.
unsafe impl Send for SecurityDescriptor {}
// SAFETY: see `Send`; no method mutates the block.
unsafe impl Sync for SecurityDescriptor {}

impl SecurityDescriptor {
    /// Parses an SDDL string. The error carries the Win32 code
    /// (`ERROR_INVALID_PARAMETER` for malformed SDDL).
    pub fn from_sddl(sddl: &str) -> io::Result<Self> {
        let sddl = wide_null(sddl)?;
        let mut descriptor = ptr::null_mut();
        // SAFETY: `sddl` is NUL-terminated; `descriptor` is a live out pointer
        // that receives a LocalAlloc block owned by the returned value.
        let converted = unsafe {
            ConvertStringSecurityDescriptorToSecurityDescriptorW(
                sddl.as_ptr(),
                SDDL_REVISION_1,
                &mut descriptor,
                ptr::null_mut(),
            )
        };
        if converted == 0 || descriptor.is_null() {
            return Err(io::Error::last_os_error());
        }
        Ok(Self(
            NonNull::new(descriptor).expect("checked non-null descriptor"),
        ))
    }

    /// A `SECURITY_ATTRIBUTES` block pointing at this descriptor, for object
    /// creation calls. It borrows the descriptor and cannot outlive it.
    pub(crate) fn attributes(&self, inherit_handle: bool) -> SecurityAttributes<'_> {
        SecurityAttributes {
            raw: SECURITY_ATTRIBUTES {
                nLength: size_of::<SECURITY_ATTRIBUTES>() as u32,
                lpSecurityDescriptor: self.0.as_ptr(),
                bInheritHandle: i32::from(inherit_handle),
            },
            _descriptor: PhantomData,
        }
    }

    /// Applies this descriptor's DACL to `path` and its whole subtree,
    /// resetting every inherited entry. With `protect` the tree also stops
    /// inheriting from its parent. The error carries the Win32 status.
    pub fn apply_to_tree(&self, path: &Path, protect: bool) -> io::Result<()> {
        let mut present = 0;
        let mut defaulted = 0;
        let mut dacl = ptr::null_mut();
        // SAFETY: `self.0` is a live descriptor and every out pointer is a
        // local; the DACL pointer stays valid while `self` is borrowed.
        let read = unsafe {
            GetSecurityDescriptorDacl(self.0.as_ptr(), &mut present, &mut dacl, &mut defaulted)
        };
        if read == 0 {
            return Err(io::Error::last_os_error());
        }
        if present == 0 || dacl.is_null() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "the descriptor has no DACL to apply",
            ));
        }
        let information = if protect {
            DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION
        } else {
            DACL_SECURITY_INFORMATION
        };
        let wide = wide_null(path)?;
        // SAFETY: `wide` is NUL-terminated; `dacl` points into the live
        // descriptor; owner, group, and SACL are null with matching flags
        // absent; no progress callback is installed.
        let status = unsafe {
            TreeSetNamedSecurityInfoW(
                wide.as_ptr(),
                SE_FILE_OBJECT,
                information,
                ptr::null_mut(),
                ptr::null_mut(),
                dacl,
                ptr::null_mut(),
                TREE_SEC_INFO_RESET,
                None,
                0,
                ptr::null(),
            )
        };
        if status != ERROR_SUCCESS {
            return Err(io::Error::from_raw_os_error(status as i32));
        }
        Ok(())
    }
}

impl Drop for SecurityDescriptor {
    fn drop(&mut self) {
        // SAFETY: the block came from the converter and is freed exactly once.
        unsafe { LocalFree(self.0.as_ptr()) };
    }
}

/// A `SECURITY_ATTRIBUTES` block that borrows its descriptor.
pub(crate) struct SecurityAttributes<'a> {
    raw: SECURITY_ATTRIBUTES,
    _descriptor: PhantomData<&'a SecurityDescriptor>,
}

impl SecurityAttributes<'_> {
    pub(crate) fn as_ptr(&self) -> *const SECURITY_ATTRIBUTES {
        &self.raw
    }
}

/// The security descriptor of an existing object, with accessors that
/// validate its parts before exposing them. Use it to verify that a pipe,
/// file or directory carries the ACL you expect.
#[derive(Debug)]
pub struct ObjectSecurityDescriptor(NonNull<c_void>);

// SAFETY: the descriptor is a LocalAlloc block owned by this value and only
// read; moving or sharing it across threads is sound.
unsafe impl Send for ObjectSecurityDescriptor {}
// SAFETY: see `Send`.
unsafe impl Sync for ObjectSecurityDescriptor {}

impl ObjectSecurityDescriptor {
    /// The DACL of the file or directory at `path`. The error carries the
    /// Win32 status, so callers can recognize a vanished path.
    pub fn query_file(path: &Path) -> io::Result<Self> {
        let wide = wide_null(path)?;
        let mut descriptor = ptr::null_mut();
        // SAFETY: `wide` is NUL-terminated, every optional output is null, and
        // `descriptor` is a live out pointer whose ownership transfers below.
        let status = unsafe {
            GetNamedSecurityInfoW(
                wide.as_ptr(),
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION,
                ptr::null_mut(),
                ptr::null_mut(),
                ptr::null_mut(),
                ptr::null_mut(),
                &mut descriptor,
            )
        };
        Self::from_query_result(status, descriptor)
    }

    /// The owner and DACL of the kernel object behind `handle`. The handle
    /// needs `READ_CONTROL`.
    pub fn query_kernel_object(handle: &impl AsHandle) -> io::Result<Self> {
        let raw = handle.as_handle().as_raw_handle();
        let mut descriptor = ptr::null_mut();
        // SAFETY: the handle is live for the call; all optional outputs are
        // null and `descriptor` is a live out pointer.
        let status = unsafe {
            GetSecurityInfo(
                raw,
                SE_KERNEL_OBJECT,
                OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION,
                ptr::null_mut(),
                ptr::null_mut(),
                ptr::null_mut(),
                ptr::null_mut(),
                &mut descriptor,
            )
        };
        Self::from_query_result(status, descriptor)
    }

    fn from_query_result(status: u32, descriptor: PSECURITY_DESCRIPTOR) -> io::Result<Self> {
        if status != ERROR_SUCCESS || descriptor.is_null() {
            if !descriptor.is_null() {
                // SAFETY: a non-null descriptor from these APIs is a LocalAlloc
                // block, even on a partial failure; it is freed exactly once.
                unsafe { LocalFree(descriptor) };
            }
            let status = if status == ERROR_SUCCESS {
                io::Error::new(io::ErrorKind::InvalidData, "Windows returned no descriptor")
            } else {
                io::Error::from_raw_os_error(status as i32)
            };
            return Err(status);
        }
        Ok(Self(
            NonNull::new(descriptor).expect("checked non-null descriptor"),
        ))
    }

    /// The descriptor control bits (for example `SE_DACL_PROTECTED`).
    pub fn control(&self) -> io::Result<u16> {
        let mut control = 0_u16;
        let mut revision = 0_u32;
        // SAFETY: `self.0` is a live descriptor; both outputs are locals.
        let read =
            unsafe { GetSecurityDescriptorControl(self.0.as_ptr(), &mut control, &mut revision) };
        if read == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(control)
    }

    /// The owner SID. Only present when the query asked for it
    /// ([`query_kernel_object`](Self::query_kernel_object) does).
    pub fn owner(&self) -> Result<ValidatedSid, SecurityAclError> {
        let mut owner = ptr::null_mut();
        let mut defaulted = 0;
        // SAFETY: `self.0` is a live descriptor; both outputs are locals. The
        // returned owner pointer is range-checked before it is read.
        let read =
            unsafe { GetSecurityDescriptorOwner(self.0.as_ptr(), &mut owner, &mut defaulted) };
        if read == 0 {
            return Err(io::Error::last_os_error().into());
        }
        if owner.is_null() {
            return Err(AclValidationError::MissingOwner.into());
        }
        ValidatedSid::from_bounded_bytes(self.bytes_from_pointer(owner.cast())?).map_err(Into::into)
    }

    /// The DACL, provided every entry in it is an access-allowed ACE.
    pub fn dacl(&self) -> Result<ValidatedDacl, SecurityAclError> {
        let mut present = 0;
        let mut defaulted = 0;
        let mut dacl = ptr::null_mut();
        // SAFETY: `self.0` is a live descriptor; all outputs are locals. The
        // returned DACL pointer is range-checked before it is read.
        let read = unsafe {
            GetSecurityDescriptorDacl(self.0.as_ptr(), &mut present, &mut dacl, &mut defaulted)
        };
        if read == 0 {
            return Err(io::Error::last_os_error().into());
        }
        if present == 0 || dacl.is_null() {
            return Err(AclValidationError::MissingDacl.into());
        }
        ValidatedDacl::from_bytes(self.bytes_from_pointer(dacl.cast())?).map_err(Into::into)
    }

    /// The bytes of the descriptor block from `pointer` to its end, provided
    /// `pointer` lies inside the block.
    fn bytes_from_pointer(&self, pointer: *const u8) -> Result<&[u8], AclValidationError> {
        // SAFETY: `self.0` is a live descriptor owned for this call.
        let length = unsafe { GetSecurityDescriptorLength(self.0.as_ptr()) } as usize;
        if length == 0 {
            return Err(AclValidationError::DescriptorRange);
        }
        let offset = (pointer as usize)
            .checked_sub(self.0.as_ptr() as usize)
            .filter(|offset| *offset < length)
            .ok_or(AclValidationError::DescriptorRange)?;
        // SAFETY: Windows reports `length` for this live LocalAlloc block, and
        // the offset was proven to fall inside it.
        let bytes = unsafe { std::slice::from_raw_parts(self.0.as_ptr().cast::<u8>(), length) };
        Ok(&bytes[offset..])
    }
}

impl Drop for ObjectSecurityDescriptor {
    fn drop(&mut self) {
        // SAFETY: this value uniquely owns the LocalAlloc block.
        unsafe { LocalFree(self.0.as_ptr()) };
    }
}

/// The calling process's user SID in string form, such as `S-1-5-18`.
pub fn current_user_sid_string() -> io::Result<String> {
    let token = [REDACTED];
    let raw = token.as_raw_handle();
    let information = probe_word_aligned(
        size_of::<TOKEN_USER>(),
        MAX_TOKEN_INFORMATION_BYTES,
        |buffer, capacity, needed| {
            // SAFETY: the token is live; the protocol passes either the
            // documented null size probe or word-aligned writable storage
            // described by `capacity`, and `needed` is a live out value.
            let result =
                unsafe { GetTokenInformation(raw, TokenUser, buffer.cast(), capacity, needed) };
            if result != 0 {
                return Ok(CallOutcome::Complete);
            }
            let error = io::Error::last_os_error();
            if error.raw_os_error() == Some(ERROR_INSUFFICIENT_BUFFER as i32) {
                Ok(CallOutcome::MoreData(error))
            } else {
                Err(error)
            }
        },
    )
    .map_err(|error| error.into_io("token user information"))?;
    // SAFETY: GetTokenInformation succeeded and the protocol verified that its
    // reported byte range holds a complete, word-aligned TOKEN_USER header.
    let user = unsafe { information.read::<TOKEN_USER>() }
        .expect("token information header size and alignment were checked");
    let sid_offset = (user.User.Sid as usize).checked_sub(information.as_ptr() as usize);
    if sid_offset.map_or(true, |offset| offset >= information.len()) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "the token user SID lies outside the returned buffer",
        ));
    }
    let mut string = ptr::null_mut();
    // SAFETY: the SID pointer lies inside the live token-information buffer
    // and `string` is a local output receiving a LocalAlloc allocation.
    if unsafe { ConvertSidToStringSidW(user.User.Sid, &mut string) } == 0 || string.is_null() {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: ConvertSidToStringSidW returned a readable NUL-terminated string;
    // it is read within a fixed bound before conversion.
    let units = unsafe { bounded_units(string, MAX_SID_STRING_UNITS) };
    let result = units
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "SID string exceeds the bound"))
        .and_then(|units| {
            String::from_utf16(units).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidData, "SID string is not valid UTF-16")
            })
        });
    // SAFETY: the string was allocated by ConvertSidToStringSidW and is freed
    // exactly once after the bounded copy.
    unsafe { LocalFree(string.cast()) };
    result
}

/// Whether the calling thread's token (or the process token, when the thread
/// is not impersonating) has `group` as an enabled group.
pub fn current_token_is_member_of(group: &OwnedSid) -> io::Result<bool> {
    let mut is_member = 0;
    // SAFETY: a null token means the current thread or process token; the
    // SID is a live LocalAlloc block owned by `group`; the output is a local.
    let checked = unsafe { CheckTokenMembership(ptr::null_mut(), group.as_ptr(), &mut is_member) };
    if checked == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(is_member != 0)
}

/// A privilege enabled in the process token for this value's lifetime, and
/// disabled again when it is dropped.
pub struct PrivilegeGuard {
    token: OwnedHandle,
    luid: LUID,
}

impl std::fmt::Debug for PrivilegeGuard {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("PrivilegeGuard")
            .field("token", &self.token)
            .field("luid_high", &self.luid.HighPart)
            .field("luid_low", &self.luid.LowPart)
            .finish()
    }
}

impl PrivilegeGuard {
    /// Enables the privilege `name`, such as `SeBackupPrivilege`. A token
    /// that does not hold the privilege fails with
    /// [`io::ErrorKind::PermissionDenied`]; enabling only works for
    /// privileges the token already has.
    pub fn enable(name: &str) -> io::Result<PrivilegeGuard> {
        let token = [REDACTED] | TOKEN_QUERY)?;
        let name_wide = wide_null(name)?;
        let mut luid = LUID::default();
        // SAFETY: `name_wide` is NUL-terminated and `luid` is a local output.
        if unsafe { LookupPrivilegeValueW(ptr::null(), name_wide.as_ptr(), &mut luid) } == 0 {
            return Err(io::Error::last_os_error());
        }
        let privileges = token_privileges(luid, SE_PRIVILEGE_ENABLED);
        // SAFETY: clearing last-error is required because a successful
        // AdjustTokenPrivileges reports partial assignment through last-error.
        unsafe { SetLastError(ERROR_SUCCESS) };
        // SAFETY: the token has adjust rights and `privileges` is a complete,
        // live one-entry TOKEN_PRIVILEGES value; previous state is not requested.
        let adjusted = unsafe {
            AdjustTokenPrivileges(
                token.as_raw_handle(),
                0,
                &privileges,
                0,
                ptr::null_mut(),
                ptr::null_mut(),
            )
        };
        if adjusted == 0 {
            return Err(io::Error::last_os_error());
        }
        let assignment = io::Error::last_os_error();
        if assignment.raw_os_error() == Some(ERROR_NOT_ALL_ASSIGNED as i32) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("the current token does not hold {name}"),
            ));
        }
        Ok(Self { token, luid })
    }
}

impl Drop for PrivilegeGuard {
    fn drop(&mut self) {
        let privileges = token_privileges(self.luid, 0);
        // SAFETY: the token remains live through drop and `privileges` is a
        // complete one-entry value; disabling is best effort by contract.
        unsafe {
            AdjustTokenPrivileges(
                self.token.as_raw_handle(),
                0,
                &privileges,
                0,
                ptr::null_mut(),
                ptr::null_mut(),
            )
        };
    }
}

fn token_privileges(luid: LUID, attributes: u32) -> TOKEN_PRIVILEGES {
    TOKEN_PRIVILEGES {
        PrivilegeCount: 1,
        Privileges: [LUID_AND_ATTRIBUTES {
            Luid: luid,
            Attributes: attributes,
        }],
    }
}

fn open_current_process_token(access: u32) -> io::Result<OwnedHandle> {
    let mut token = [REDACTED];
    // SAFETY: the process pseudo-handle is always valid and `token` is a local
    // out pointer whose handle is owned immediately below.
    if unsafe { OpenProcessToken(current_process(), access, &mut token) } == 0 {
        return Err(io::Error::last_os_error());
    }
    owned_from_creation(token)
}

#[cfg(test)]
mod tests {
    use windows_sys::Win32::Foundation::ERROR_INVALID_PARAMETER;

    use super::{
        current_token_is_member_of, current_user_sid_string, ObjectSecurityDescriptor, OwnedSid,
        PrivilegeGuard, SecurityDescriptor,
    };

    #[test]
    fn a_tree_reset_from_sddl_reads_back_as_the_same_allowed_aces() {
        let directory = tempfile::tempdir().unwrap();
        let child = directory.path().join("child");
        std::fs::create_dir(&child).unwrap();
        let current_user = current_user_sid_string().unwrap();
        let sddl = format!("D:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)(A;OICI;FA;;;{current_user})");
        let descriptor = SecurityDescriptor::from_sddl(&sddl).unwrap();
        descriptor.apply_to_tree(directory.path(), true).unwrap();

        let system = OwnedSid::from_string("S-1-5-18").unwrap();
        let queried = ObjectSecurityDescriptor::query_file(&child).unwrap();
        let dacl = queried.dacl().unwrap();
        assert_eq!(dacl.len(), 3);
        assert!(dacl.allowed_aces().any(|ace| ace.trustee_matches(&system)));
        assert!(ObjectSecurityDescriptor::query_file(&directory.path().join("missing")).is_err());
    }

    #[test]
    fn malformed_sddl_reports_invalid_parameter() {
        let error = SecurityDescriptor::from_sddl("D:(not sddl").unwrap_err();
        assert_eq!(error.raw_os_error(), Some(ERROR_INVALID_PARAMETER as i32));
    }

    #[test]
    fn the_current_user_sid_has_a_decimal_sid_shape() {
        let sid = current_user_sid_string().unwrap();
        assert!(sid.starts_with("S-1-"), "unexpected SID {sid}");
        assert!(sid[4..].split('-').all(|component| !component.is_empty()
            && component.bytes().all(|byte| byte.is_ascii_digit())));
    }

    #[test]
    fn every_token_is_a_member_of_everyone() {
        let everyone = OwnedSid::from_string("WD").unwrap();
        assert!(current_token_is_member_of(&everyone).unwrap());
    }

    #[test]
    fn held_privileges_enable_and_unknown_names_fail() {
        drop(PrivilegeGuard::enable("SeChangeNotifyPrivilege").unwrap());
        assert!(PrivilegeGuard::enable("SeNotARealPrivilege").is_err());
    }
}

//! SIDs and DACLs as validated byte structures.
#![allow(unsafe_code)]

use std::ffi::c_void;
use std::fmt;
use std::io;
use std::mem::{offset_of, size_of};
use std::ptr::{self, NonNull};

use windows_sys::Win32::Foundation::LocalFree;
use windows_sys::Win32::Security::Authorization:[REDACTED];
use windows_sys::Win32::Security::{
    GetLengthSid, IsValidSid, ACCESS_ALLOWED_ACE, ACE_HEADER, ACL, PSID,
};

use crate::wide::wide_null;

const ACCESS_ALLOWED_ACE_KIND: u8 = 0;
const SID_FIXED_BYTES: usize = 8;
const SID_SUB_AUTHORITY_BYTES: usize = size_of::<u32>();
const ACE_HEADER_BYTES: usize = size_of::<ACE_HEADER>();
const ACL_HEADER_BYTES: usize = size_of::<ACL>();
const ACCESS_ALLOWED_SID_OFFSET: usize = offset_of!(ACCESS_ALLOWED_ACE, SidStart);

/// Why a descriptor's bytes did not form the structure Windows claims.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum AclValidationError {
    /// A pointer Windows returned lies outside the descriptor block.
    DescriptorRange,
    /// The descriptor has no DACL.
    MissingDacl,
    /// The descriptor has no owner.
    MissingOwner,
    /// The ACL is shorter than its header.
    AclTooShort,
    /// The ACL's declared size is smaller than its header or larger than the
    /// bytes available.
    InvalidAclSize,
    /// An ACE header runs past the end of the ACL.
    TruncatedAceHeader,
    /// An ACE declares a size that is too small or not a multiple of four.
    InvalidAceSize,
    /// An ACE runs past the end of the ACL.
    AceOutOfRange,
    /// An ACE is not an `ACCESS_ALLOWED_ACE`. Deny and audit entries are
    /// rejected so a policy check cannot overlook them.
    UnsupportedAceType,
    /// A SID runs past the end of its container.
    TruncatedSid,
    /// Windows rejected a SID's structure.
    InvalidSid,
}

impl fmt::Display for AclValidationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let message = match self {
            Self::DescriptorRange => "a descriptor pointer lies outside the descriptor",
            Self::MissingDacl => "the descriptor has no DACL",
            Self::MissingOwner => "the descriptor has no owner",
            Self::AclTooShort => "the ACL is shorter than its header",
            Self::InvalidAclSize => "the ACL size is out of range",
            Self::TruncatedAceHeader => "an ACE header is truncated",
            Self::InvalidAceSize => "an ACE size is invalid",
            Self::AceOutOfRange => "an ACE runs past the end of the ACL",
            Self::UnsupportedAceType => "the ACL contains an ACE that is not access-allowed",
            Self::TruncatedSid => "a SID is truncated",
            Self::InvalidSid => "a SID is invalid",
        };
        formatter.write_str(message)
    }
}

impl std::error::Error for AclValidationError {}

/// A failure while reading part of a security descriptor.
#[derive(Debug)]
#[non_exhaustive]
pub enum SecurityAclError {
    /// The Win32 call failed.
    Io(io::Error),
    /// The bytes Windows returned did not validate.
    Invalid(AclValidationError),
}

impl fmt::Display for SecurityAclError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(error) => error.fmt(formatter),
            Self::Invalid(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for SecurityAclError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io(error) => Some(error),
            Self::Invalid(error) => Some(error),
        }
    }
}

impl From<io::Error> for SecurityAclError {
    fn from(value: io::Error) -> Self {
        Self::Io(value)
    }
}

impl From<AclValidationError> for SecurityAclError {
    fn from(value: AclValidationError) -> Self {
        Self::Invalid(value)
    }
}

/// A SID converted from its string form, kept both as the Windows allocation
/// (for APIs that need a pointer) and as validated bytes (for comparison).
#[derive(Debug)]
pub struct OwnedSid {
    raw: NonNull<c_void>,
    bytes: Vec<u8>,
}

impl OwnedSid {
    /// Converts a SID in string form, such as `S-1-5-18` or the SDDL alias
    /// `SY`.
    pub fn from_string(value: &str) -> io::Result<Self> {
        let value = wide_null(value)?;
        let mut sid = ptr::null_mut();
        // SAFETY: the SDDL string is NUL-terminated and `sid` is a live out
        // pointer; on success the LocalAlloc block is owned below.
        if unsafe { ConvertStringSidToSidW(value.as_ptr(), &mut sid) } == 0 || sid.is_null() {
            return Err(io::Error::last_os_error());
        }
        let raw = NonNull::new(sid).expect("checked non-null SID");
        let free = |raw: NonNull<c_void>| {
            // SAFETY: the failed validation path still uniquely owns the block.
            unsafe { LocalFree(raw.as_ptr()) };
        };
        // SAFETY: `raw` was just returned by the converter.
        if unsafe { IsValidSid(raw.as_ptr()) } == 0 {
            free(raw);
            return Err(invalid_data("Windows returned an invalid converted SID"));
        }
        // SAFETY: IsValidSid accepted this block.
        let length = unsafe { GetLengthSid(raw.as_ptr()) } as usize;
        if length < SID_FIXED_BYTES {
            free(raw);
            return Err(invalid_data("Windows returned a truncated converted SID"));
        }
        // SAFETY: GetLengthSid reported the initialized length of this block.
        let bytes =
            unsafe { std::slice::from_raw_parts(raw.as_ptr().cast::<u8>(), length) }.to_vec();
        Ok(Self { raw, bytes })
    }

    pub(crate) fn as_ptr(&self) -> PSID {
        self.raw.as_ptr()
    }
}

impl Drop for OwnedSid {
    fn drop(&mut self) {
        // SAFETY: this value uniquely owns the converter's LocalAlloc block.
        unsafe { LocalFree(self.raw.as_ptr()) };
    }
}

/// A SID copied out of a descriptor after its structure was verified.
#[derive(Debug)]
pub struct ValidatedSid {
    bytes: Vec<u8>,
}

impl ValidatedSid {
    pub(crate) fn from_bounded_bytes(bytes: &[u8]) -> Result<Self, AclValidationError> {
        if bytes.len() < SID_FIXED_BYTES {
            return Err(AclValidationError::TruncatedSid);
        }
        let sub_authorities = usize::from(bytes[1]);
        let length = sub_authorities
            .checked_mul(SID_SUB_AUTHORITY_BYTES)
            .and_then(|tail| SID_FIXED_BYTES.checked_add(tail))
            .ok_or(AclValidationError::TruncatedSid)?;
        if length > bytes.len() {
            return Err(AclValidationError::TruncatedSid);
        }
        // Windows SID routines expect an aligned SID. Copying the bounded
        // bytes into u32 storage keeps that invariant local to this function.
        let mut aligned = vec![0_u32; length.div_ceil(size_of::<u32>())];
        // SAFETY: the byte view covers exactly the initialized u32 allocation,
        // does not outlive `aligned`, and keeps its four-byte alignment.
        let aligned_bytes = unsafe {
            std::slice::from_raw_parts_mut(
                aligned.as_mut_ptr().cast::<u8>(),
                aligned.len() * size_of::<u32>(),
            )
        };
        aligned_bytes[..length].copy_from_slice(&bytes[..length]);
        let sid = aligned.as_mut_ptr().cast::<c_void>();
        // SAFETY: the structural check above proved every sub-authority byte
        // is present in this aligned allocation.
        if unsafe { IsValidSid(sid) } == 0 {
            return Err(AclValidationError::InvalidSid);
        }
        // SAFETY: IsValidSid accepted the bounded, aligned SID.
        let windows_length = unsafe { GetLengthSid(sid) } as usize;
        if windows_length != length {
            return Err(AclValidationError::InvalidSid);
        }
        Ok(Self {
            bytes: bytes[..length].to_vec(),
        })
    }

    /// Whether this SID is byte-for-byte the same as `expected`.
    pub fn matches(&self, expected: &OwnedSid) -> bool {
        self.bytes == expected.bytes
    }
}

/// One `ACCESS_ALLOWED_ACE`, reduced to the fields policy checks read.
#[derive(Debug)]
pub struct AllowedAce {
    flags: u8,
    mask: u32,
    trustee: ValidatedSid,
}

impl AllowedAce {
    /// The ACE flags, such as `OBJECT_INHERIT_ACE` and `INHERITED_ACE`.
    pub const fn flags(&self) -> u8 {
        self.flags
    }

    /// The access mask the ACE grants.
    pub const fn mask(&self) -> u32 {
        self.mask
    }

    /// Whether the ACE grants its rights to `expected`.
    pub fn trustee_matches(&self, expected: &OwnedSid) -> bool {
        self.trustee.matches(expected)
    }
}

/// A DACL whose every ACE was an in-bounds `ACCESS_ALLOWED_ACE` with a
/// well-formed SID. Any other ACE type fails validation, so a policy that
/// iterates this list has already excluded deny and audit entries.
#[derive(Debug)]
pub struct ValidatedDacl {
    allowed_aces: Vec<AllowedAce>,
}

impl ValidatedDacl {
    pub(crate) fn from_bytes(bytes: &[u8]) -> Result<Self, AclValidationError> {
        if bytes.len() < ACL_HEADER_BYTES {
            return Err(AclValidationError::AclTooShort);
        }
        let acl_size = usize::from(u16::from_le_bytes([bytes[2], bytes[3]]));
        if acl_size < ACL_HEADER_BYTES || acl_size > bytes.len() {
            return Err(AclValidationError::InvalidAclSize);
        }
        let ace_count = usize::from(u16::from_le_bytes([bytes[4], bytes[5]]));
        let bytes = &bytes[..acl_size];
        if ace_count > (bytes.len() - ACL_HEADER_BYTES) / ACE_HEADER_BYTES {
            return Err(AclValidationError::TruncatedAceHeader);
        }
        let mut offset = ACL_HEADER_BYTES;
        let mut allowed_aces = Vec::with_capacity(ace_count);
        for _ in 0..ace_count {
            let header_end = offset
                .checked_add(ACE_HEADER_BYTES)
                .filter(|end| *end <= bytes.len())
                .ok_or(AclValidationError::TruncatedAceHeader)?;
            let ace_type = bytes[offset];
            let flags = bytes[offset + 1];
            let ace_size = usize::from(u16::from_le_bytes([bytes[offset + 2], bytes[offset + 3]]));
            if ace_size < ACE_HEADER_BYTES || ace_size % size_of::<u32>() != 0 {
                return Err(AclValidationError::InvalidAceSize);
            }
            let ace_end = offset
                .checked_add(ace_size)
                .filter(|end| *end <= bytes.len())
                .ok_or(AclValidationError::AceOutOfRange)?;
            debug_assert!(header_end <= ace_end);
            if ace_type != ACCESS_ALLOWED_ACE_KIND {
                return Err(AclValidationError::UnsupportedAceType);
            }
            if ace_size < ACCESS_ALLOWED_SID_OFFSET + SID_FIXED_BYTES {
                return Err(AclValidationError::InvalidAceSize);
            }
            let mask_offset = offset + offset_of!(ACCESS_ALLOWED_ACE, Mask);
            let mask = u32::from_le_bytes(
                bytes[mask_offset..mask_offset + size_of::<u32>()]
                    .try_into()
                    .expect("validated access mask range"),
            );
            let trustee = ValidatedSid::from_bounded_bytes(
                &bytes[offset + ACCESS_ALLOWED_SID_OFFSET..ace_end],
            )?;
            allowed_aces.push(AllowedAce {
                flags,
                mask,
                trustee,
            });
            offset = ace_end;
        }
        Ok(Self { allowed_aces })
    }

    /// The number of ACEs.
    pub fn len(&self) -> usize {
        self.allowed_aces.len()
    }

    /// Whether the DACL has no ACEs, which denies everyone.
    pub fn is_empty(&self) -> bool {
        self.allowed_aces.is_empty()
    }

    /// The ACEs in order.
    pub fn allowed_aces(&self) -> impl Iterator<Item = &AllowedAce> {
        self.allowed_aces.iter()
    }
}

fn invalid_data(message: &str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}

#[cfg(test)]
mod tests {
    use super::{AclValidationError, OwnedSid, ValidatedDacl};

    const SYSTEM_SID_BYTES: [u8; 12] = [1, 1, 0, 0, 0, 0, 0, 5, 18, 0, 0, 0];

    fn valid_acl() -> Vec<u8> {
        let ace_size = 8 + SYSTEM_SID_BYTES.len();
        let acl_size = 8 + ace_size;
        let mut acl = vec![0_u8; acl_size];
        acl[0] = 2;
        acl[2..4].copy_from_slice(&(acl_size as u16).to_le_bytes());
        acl[4..6].copy_from_slice(&1_u16.to_le_bytes());
        acl[9] = 0x10;
        acl[10..12].copy_from_slice(&(ace_size as u16).to_le_bytes());
        acl[12..16].copy_from_slice(&0x001f_0001_u32.to_le_bytes());
        acl[16..].copy_from_slice(&SYSTEM_SID_BYTES);
        acl
    }

    #[test]
    fn a_valid_allowed_ace_exposes_only_validated_fields() {
        let dacl = ValidatedDacl::from_bytes(&valid_acl()).unwrap();
        let system = OwnedSid::from_string("S-1-5-18").unwrap();
        let ace = dacl.allowed_aces().next().unwrap();
        assert_eq!(dacl.len(), 1);
        assert_eq!(ace.flags(), 0x10);
        assert_eq!(ace.mask(), 0x001f_0001);
        assert!(ace.trustee_matches(&system));
    }

    #[test]
    fn malformed_acls_are_rejected_at_the_first_inconsistent_field() {
        assert_eq!(
            ValidatedDacl::from_bytes(&[0; 7]).unwrap_err(),
            AclValidationError::AclTooShort
        );
        let mut undersized = valid_acl();
        undersized[2..4].copy_from_slice(&7_u16.to_le_bytes());
        assert_eq!(
            ValidatedDacl::from_bytes(&undersized).unwrap_err(),
            AclValidationError::InvalidAclSize
        );
        let mut short_ace = valid_acl();
        short_ace[10..12].copy_from_slice(&12_u16.to_le_bytes());
        assert_eq!(
            ValidatedDacl::from_bytes(&short_ace).unwrap_err(),
            AclValidationError::InvalidAceSize
        );
        let mut long_ace = valid_acl();
        let ace_size = long_ace.len() as u16;
        long_ace[10..12].copy_from_slice(&ace_size.to_le_bytes());
        assert_eq!(
            ValidatedDacl::from_bytes(&long_ace).unwrap_err(),
            AclValidationError::AceOutOfRange
        );
        let mut truncated_sid = valid_acl();
        truncated_sid[10..12].copy_from_slice(&16_u16.to_le_bytes());
        assert_eq!(
            ValidatedDacl::from_bytes(&truncated_sid).unwrap_err(),
            AclValidationError::TruncatedSid
        );
        let mut invalid_sid = valid_acl();
        invalid_sid[16] = 0;
        assert_eq!(
            ValidatedDacl::from_bytes(&invalid_sid).unwrap_err(),
            AclValidationError::InvalidSid
        );
        let mut deny = valid_acl();
        deny[8] = 1;
        assert_eq!(
            ValidatedDacl::from_bytes(&deny).unwrap_err(),
            AclValidationError::UnsupportedAceType
        );
    }
}

//! Owned kernel handles and bounded waits.
#![allow(unsafe_code)]

use std::io;
use std::os::windows::io::{AsHandle, AsRawHandle, FromRawHandle, OwnedHandle};
use std::time::Duration;

use windows_sys::Win32::Foundation::{
    HANDLE, INVALID_HANDLE_VALUE, WAIT_ABANDONED, WAIT_FAILED, WAIT_OBJECT_0, WAIT_TIMEOUT,
};
use windows_sys::Win32::System::Threading::{GetCurrentProcess, WaitForSingleObject};

/// How a wait on a kernel object ended.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum WaitOutcome {
    /// The object became signaled: a process or thread exited, an event was
    /// set, a mutex was acquired.
    Signaled,
    /// The timeout passed first.
    TimedOut,
    /// A mutex whose previous owner exited without releasing it. The wait
    /// still acquired ownership.
    Abandoned,
}

/// Waits until the object behind `handle` is signaled or `timeout` passes.
/// `None` waits forever.
///
/// Works on anything that exposes a waitable handle: a [`crate::Process`],
/// a [`std::process::Child`], an event or a mutex.
pub fn wait(handle: &impl AsHandle, timeout: Option<Duration>) -> io::Result<WaitOutcome> {
    let milliseconds = timeout.map_or(u32::MAX, clamp_timeout);
    let raw = handle.as_handle().as_raw_handle();
    // SAFETY: `raw` comes from a live borrowed handle that outlives the call;
    // the wait takes no pointers.
    match unsafe { WaitForSingleObject(raw, milliseconds) } {
        WAIT_OBJECT_0 => Ok(WaitOutcome::Signaled),
        WAIT_TIMEOUT => Ok(WaitOutcome::TimedOut),
        WAIT_ABANDONED => Ok(WaitOutcome::Abandoned),
        WAIT_FAILED => Err(io::Error::last_os_error()),
        other => Err(io::Error::other(format!(
            "unexpected wait result {other:#x}"
        ))),
    }
}

/// Whether the object is signaled right now.
#[cfg(test)]
pub(crate) fn is_signaled(handle: &impl AsHandle) -> bool {
    matches!(
        wait(handle, Some(Duration::ZERO)),
        Ok(WaitOutcome::Signaled | WaitOutcome::Abandoned)
    )
}

/// The current-process pseudo-handle. It is always valid and never needs to
/// be closed.
pub(crate) fn current_process() -> HANDLE {
    // SAFETY: GetCurrentProcess takes no arguments and returns a constant
    // pseudo-handle.
    unsafe { GetCurrentProcess() }
}

/// Takes ownership of a handle that a Win32 creation or open call just
/// returned. Creation calls report failure as either null or
/// `INVALID_HANDLE_VALUE`, so both become the call's `GetLastError` value,
/// read before anything else can overwrite it.
pub(crate) fn owned_from_creation(handle: HANDLE) -> io::Result<OwnedHandle> {
    if handle.is_null() || handle == INVALID_HANDLE_VALUE {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: the handle was just returned by a successful creation or open
    // call, nothing else owns it, and `OwnedHandle` closes it exactly once.
    Ok(unsafe { OwnedHandle::from_raw_handle(handle) })
}

/// Converts a wait duration into the millisecond count Win32 expects, keeping
/// `u32::MAX` (`INFINITE`) reserved for the explicit "wait forever" case.
pub(crate) fn clamp_timeout(timeout: Duration) -> u32 {
    timeout.as_millis().min(u128::from(u32::MAX - 1)) as u32
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use super::clamp_timeout;

    #[test]
    fn timeouts_never_collapse_into_infinite() {
        assert_eq!(clamp_timeout(Duration::ZERO), 0);
        assert_eq!(clamp_timeout(Duration::from_millis(250)), 250);
        assert_eq!(clamp_timeout(Duration::from_secs(u64::MAX)), u32::MAX - 1);
    }
}

//! Take custody of Windows child processes.
//!
//! A parent that launches helpers on Windows has to decide four things for
//! every child, and the Win32 defaults get each of them wrong for a service or
//! a launcher:
//!
//! * **What it inherits.** [`Launch`] passes an explicit
//!   `PROC_THREAD_ATTRIBUTE_HANDLE_LIST`, so the child receives exactly the
//!   handles you name and nothing else that happens to be inheritable in your
//!   process. The standard library cannot do this on stable Rust.
//! * **How long it lives.** [`Job`] puts the child in a kill-on-close job
//!   object before its first instruction runs, so it cannot outlive you, even
//!   when your process is killed.
//! * **Who it runs as.** [`PrimaryToken`] lets a service start the child in
//!   another session, as the logged-on user or as itself on that user's
//!   desktop.
//! * **Who can reach it.** [`SecurityDescriptor`] turns SDDL into the access
//!   rules for the pipes ([`PipeServer`]), mutexes ([`NamedMutex`]), jobs and
//!   directory trees you share with the child, and [`PipeServer`] tells you the
//!   process ID of whoever connected.
//!
//! # Not a sandbox
//!
//! Nothing here confines what a child can do with the rights its token
//! already has. A job object ties the child's lifetime and resource use to
//! yours; it does not stop the child from reading files, writing the registry
//! or opening network connections. Run untrusted code in an AppContainer or
//! a separate low-privilege account instead.
//!
//! # Example
//!
//! ```no_run
//! # #[cfg(windows)]
//! # fn main() -> std::io::Result<()> {
//! use std::time::Duration;
//! use win_custody::{Job, JobLimits, Launch, WaitOutcome};
//!
//! let job = Job::create(&JobLimits::new().kill_on_close(true))?;
//! let child = Launch::new(r"C:\Windows\System32\cmd.exe")
//!     .args(["/d", "/c", "exit 7"])
//!     .spawn_in_job(&job)?;
//! assert_eq!(child.wait(Some(Duration::from_secs(10)))?, WaitOutcome::Signaled);
//! assert_eq!(child.exit_code()?, Some(7));
//! # Ok(())
//! # }
//! # #[cfg(not(windows))]
//! # fn main() {}
//! ```
//!
//! # Where the `unsafe` lives
//!
//! `unsafe_code` is denied for the crate. Only the modules that call Win32
//! opt back in, each at its top, and every `unsafe` block there carries a
//! `SAFETY:` comment naming the invariant it relies on. Raw handles,
//! pointers and buffer lengths never cross the public API: handles come and
//! go as [`std::os::windows::io::OwnedHandle`] and
//! [`std::os::windows::io::BorrowedHandle`], and buffers Windows fills are
//! bounds-checked before they are read.
//!
//! On targets other than Windows the crate compiles to nothing.
#![cfg(windows)]

mod bounded_read;
mod event;
mod handle;
mod job;
