//! UTF-16 conversions. A NUL-terminated buffer is only ever read up to a
//! caller-supplied maximum, so a missing terminator cannot turn into a read
//! past the allocation.
#![allow(unsafe_code)]

use std::ffi::OsStr;
use std::io;
use std::os::windows::ffi::OsStrExt;

/// Encodes `value` as NUL-terminated UTF-16 for a Win32 `LPCWSTR` argument.
/// An interior NUL would silently truncate the string on the Win32 side, so
/// it is rejected.
pub(crate) fn wide_null(value: impl AsRef<OsStr>) -> io::Result<Vec<u16>> {
    let mut units: Vec<u16> = value.as_ref().encode_wide().collect();
    if units.contains(&0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "string contains an interior NUL",
        ));
    }
    units.push(0);
    Ok(units)
}

/// Reads a NUL-terminated UTF-16 string of at most `maximum` units from
/// `pointer`. Returns `None` for a null pointer or when no terminator appears
/// inside the bound, so callers see "unreadable" rather than a truncated value.
///
/// # Safety
///
/// `pointer` must either be null or point at readable memory that stays valid
/// for `maximum` UTF-16 units or up to and including its NUL terminator,
/// whichever comes first.
pub(crate) unsafe fn bounded_units<'a>(pointer: *const u16, maximum: usize) -> Option<&'a [u16]> {
    if pointer.is_null() {
        return None;
    }
    let mut length = 0_usize;
    while length < maximum {
        let unit = pointer.wrapping_add(length);
        // SAFETY: the caller guarantees the buffer is readable up to `maximum`
        // units or its terminator; the loop stops at whichever comes first,
        // so `unit` is inside the readable range.
        if unsafe { *unit } == 0 {
            break;
        }
        length += 1;
    }
    if length == maximum {
        return None;
    }
    // SAFETY: every unit in `..length` was just read through the same pointer.
    Some(unsafe { std::slice::from_raw_parts(pointer, length) })
}

/// Converts a bounded UTF-16 read into a `String`, rejecting invalid UTF-16.
///
/// # Safety
///
/// Same contract as [`bounded_units`].
pub(crate) unsafe fn bounded_string(pointer: *const u16, maximum: usize) -> Option<String> {
    // SAFETY: forwarded verbatim to the caller's guarantee.
    unsafe { bounded_units(pointer, maximum) }.and_then(|units| String::from_utf16(units).ok())
}

#[cfg(test)]
mod tests {
    use super::{bounded_units, wide_null};

    #[test]
    fn bounded_reads_stop_at_the_terminator_and_reject_missing_ones() {
        let terminated: Vec<u16> = "abc".encode_utf16().chain(Some(0)).collect();
        // SAFETY: the buffer is a live Vec with a terminator inside the bound.
        let read = unsafe { bounded_units(terminated.as_ptr(), 8) }.unwrap();
        assert_eq!(String::from_utf16_lossy(read), "abc");

        let unterminated: Vec<u16> = "abcd".encode_utf16().collect();
        // SAFETY: the bound equals the buffer length, so no unit past it is read.
        assert!(unsafe { bounded_units(unterminated.as_ptr(), 4) }.is_none());
        // SAFETY: a null pointer is never dereferenced.
        assert!(unsafe { bounded_units(std::ptr::null(), 4) }.is_none());
    }

    #[test]
    fn wide_null_appends_a_terminator_and_rejects_interior_nuls() {
        assert_eq!(wide_null("x").unwrap(), [u16::from(b'x'), 0]);
        assert!(wide_null("a\0b").is_err());
    }
}

//! Manual-reset events for overlapped I/O.
#![allow(unsafe_code)]

use std::io;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle};
use std::ptr::null;

use windows_sys::Win32::Foundation::HANDLE;
use windows_sys::Win32::System::Threading::CreateEventW;

use crate::handle::owned_from_creation;

/// An anonymous manual-reset event that starts unsignaled.
#[derive(Debug)]
pub(crate) struct ManualResetEvent(OwnedHandle);

impl ManualResetEvent {
    pub(crate) fn new() -> io::Result<Self> {
        // SAFETY: no security attributes and no name are passed; the integer
        // flags request a manual-reset event that starts unsignaled.
        let handle = unsafe { CreateEventW(null(), 1, 0, null()) };
        Ok(Self(owned_from_creation(handle)?))
    }

    pub(crate) fn as_raw(&self) -> HANDLE {
        self.0.as_raw_handle()
    }
}

impl AsHandle for ManualResetEvent {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use super::ManualResetEvent;
    use crate::handle::{is_signaled, wait, WaitOutcome};

    #[test]
    fn a_new_event_is_unsignaled() {
        let event = ManualResetEvent::new().unwrap();
        assert!(!is_signaled(&event));
        assert_eq!(
            wait(&event, Some(Duration::ZERO)).unwrap(),
            WaitOutcome::TimedOut
        );
    }
}

//! Terminal Services sessions.
#![allow(unsafe_code)]

use std::io;
use std::ptr::null_mut;

use windows_sys::Win32::System::RemoteDesktop::{
    ProcessIdToSessionId, WTSEnumerateProcessesW, WTSFreeMemory, WTSGetActiveConsoleSessionId,
    WTS_PROCESS_INFOW,
};

use crate::wide::bounded_string;

const MAX_PROCESS_NAME_UNITS: usize = 32_768;
const NO_CONSOLE_SESSION: u32 = 0xFFFF_FFFF;

/// The session the calling process runs in.
pub fn current_session_id() -> io::Result<u32> {
    process_session_id(std::process::id())
}

/// The session the process with `pid` runs in.
pub fn process_session_id(pid: u32) -> io::Result<u32> {
    let mut session_id = 0;
    // SAFETY: plain integer in, local `u32` out.
    if unsafe { ProcessIdToSessionId(pid, &mut session_id) } == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(session_id)
}

/// The session attached to the physical console, or `None` while the console
/// is between sessions (during a user switch, for example).
pub fn active_console_session_id() -> Option<u32> {
    // SAFETY: the call takes no arguments.
    let session = unsafe { WTSGetActiveConsoleSessionId() };
    (session != NO_CONSOLE_SESSION).then_some(session)
}

/// One process as Terminal Services reports it.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SessionProcess {
    /// The process ID.
    pub pid: u32,
    /// The session the process runs in.
    pub session_id: u32,
    /// The image name, or `None` when it was unreadable or exceeded a fixed
    /// bound.
    pub name: Option<String>,
}

/// Every process on the local machine with its session, copied out of the
/// Terminal Services buffer before it is freed.
pub fn session_processes() -> io::Result<Vec<SessionProcess>> {
    let mut processes = null_mut();
    let mut count = 0_u32;
    // SAFETY: a null server handle means the local machine; both out pointers
    // are locals that receive a WTS-allocated array and its length.
    if unsafe { WTSEnumerateProcessesW(null_mut(), 0, 1, &mut processes, &mut count) } == 0 {
        return Err(io::Error::last_os_error());
    }
    let list = WtsProcessList(processes);
    if count == 0 {
        return Ok(Vec::new());
    }
    if list.0.is_null() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "Terminal Services reported processes without a buffer",
        ));
    }
    // SAFETY: WTS returned `count` contiguous entries in `list.0`, which stays
    // allocated until `list` is dropped after this copy.
    let entries = unsafe { std::slice::from_raw_parts(list.0, count as usize) };
    Ok(entries
        .iter()
        .map(|entry| SessionProcess {
            pid: entry.ProcessId,
            session_id: entry.SessionId,
            // SAFETY: the name pointer belongs to the same WTS allocation and
            // is read within a fixed bound.
            name: unsafe { bounded_string(entry.pProcessName, MAX_PROCESS_NAME_UNITS) },
        })
        .collect())
}

struct WtsProcessList(*mut WTS_PROCESS_INFOW);

impl Drop for WtsProcessList {
    fn drop(&mut self) {
        if !self.0.is_null() {
            // SAFETY: the buffer was allocated by WTSEnumerateProcessesW and is
            // freed exactly once.
            unsafe { WTSFreeMemory(self.0.cast()) };
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{current_session_id, session_processes};

    #[test]
    fn the_current_process_appears_with_its_session_and_name() {
        let processes = session_processes().unwrap();
        let own = processes
            .iter()
            .find(|process| process.pid == std::process::id())
            .expect("the enumerating process is listed");
        assert!(own.name.as_deref().is_some_and(|name| !name.is_empty()));
        assert_eq!(own.session_id, current_session_id().unwrap());
    }
}

//! Job objects that bind a child's lifetime and resources to the parent.
#![allow(unsafe_code)]

use std::io;
use std::mem::size_of;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle, RawHandle};
use std::ptr::{null, null_mut};

use windows_sys::Win32::System::JobObjects::{
    AssignProcessToJobObject, CreateJobObjectW, JobObjectExtendedLimitInformation,
    QueryInformationJobObject, SetInformationJobObject, TerminateJobObject,
    JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JOB_OBJECT_LIMIT_ACTIVE_PROCESS,
    JOB_OBJECT_LIMIT_JOB_MEMORY, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
    JOB_OBJECT_LIMIT_PROCESS_MEMORY,
};

use crate::handle::{current_process, owned_from_creation};
use crate::security::SecurityDescriptor;

/// The limits a [`Job`] enforces.
///
/// Built with the setter methods, which can be chained:
///
/// ```
/// # #[cfg(windows)] {
/// use win_custody::JobLimits;
///
/// let limits = JobLimits::new()
///     .kill_on_close(true)
///     .active_processes(1)
///     .process_memory(256 * 1024 * 1024);
/// assert!(limits.kills_on_close());
/// assert_eq!(limits.active_process_limit(), Some(1));
/// # }
/// ```
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct JobLimits {
    kill_on_close: bool,
    active_processes: Option<u32>,
    process_memory: Option<usize>,
    job_memory: Option<usize>,
}

impl JobLimits {
    /// No limits at all.
    pub const fn new() -> Self {
        Self {
            kill_on_close: false,
            active_processes: None,
            process_memory: None,
            job_memory: None,
        }
    }

    /// Kill every process in the job when the last handle to the job closes,
    /// including when the owning process is killed.
    #[must_use]
    pub const fn kill_on_close(mut self, enabled: bool) -> Self {
        self.kill_on_close = enabled;
        self
    }

    /// At most `limit` processes may be active in the job at once. Assigning
    /// or creating one more fails.
    #[must_use]
    pub const fn active_processes(mut self, limit: u32) -> Self {
        self.active_processes = Some(limit);
        self
    }

    /// Each process may commit at most `bytes` of memory.
    #[must_use]
    pub const fn process_memory(mut self, bytes: usize) -> Self {
        self.process_memory = Some(bytes);
        self
    }

    /// All processes in the job together may commit at most `bytes`.
    #[must_use]
    pub const fn job_memory(mut self, bytes: usize) -> Self {
        self.job_memory = Some(bytes);
        self
    }

    /// Whether the job kills its processes when its last handle closes.
    pub const fn kills_on_close(&self) -> bool {
        self.kill_on_close
    }

    /// The active-process limit, if one is set.
    pub const fn active_process_limit(&self) -> Option<u32> {
        self.active_processes
    }

    /// The per-process commit limit in bytes, if one is set.
    pub const fn process_memory_limit(&self) -> Option<usize> {
        self.process_memory
    }

    /// The whole-job commit limit in bytes, if one is set.
    pub const fn job_memory_limit(&self) -> Option<usize> {
        self.job_memory
    }

    fn validate(&self) -> io::Result<()> {
        if self.active_processes == Some(0)
            || self.process_memory == Some(0)
            || self.job_memory == Some(0)
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "a zero job limit would refuse every process",
            ));
        }
        Ok(())
    }

    fn to_raw(self) -> JOBOBJECT_EXTENDED_LIMIT_INFORMATION {
        let mut raw = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        let basic = &mut raw.BasicLimitInformation;
        if self.kill_on_close {
            basic.LimitFlags |= JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        }
        if let Some(limit) = self.active_processes {
            basic.LimitFlags |= JOB_OBJECT_LIMIT_ACTIVE_PROCESS;
            basic.ActiveProcessLimit = limit;
        }
        if let Some(bytes) = self.process_memory {
            basic.LimitFlags |= JOB_OBJECT_LIMIT_PROCESS_MEMORY;
            raw.ProcessMemoryLimit = bytes;
        }
        if let Some(bytes) = self.job_memory {
            raw.BasicLimitInformation.LimitFlags |= JOB_OBJECT_LIMIT_JOB_MEMORY;
            raw.JobMemoryLimit = bytes;
        }
        raw
    }

    fn from_raw(raw: &JOBOBJECT_EXTENDED_LIMIT_INFORMATION) -> Self {
        let flags = raw.BasicLimitInformation.LimitFlags;
        Self {
            kill_on_close: flags & JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE != 0,
            active_processes: (flags & JOB_OBJECT_LIMIT_ACTIVE_PROCESS != 0)
                .then_some(raw.BasicLimitInformation.ActiveProcessLimit),
            process_memory: (flags & JOB_OBJECT_LIMIT_PROCESS_MEMORY != 0)
                .then_some(raw.ProcessMemoryLimit),
            job_memory: (flags & JOB_OBJECT_LIMIT_JOB_MEMORY != 0).then_some(raw.JobMemoryLimit),
        }
    }
}

/// An anonymous job object whose limits are in force before the first
/// process can join it.
#[derive(Debug)]
pub struct Job(OwnedHandle);

impl Job {
    /// Creates a job with `limits` and the creator's default security.
    pub fn create(limits: &JobLimits) -> io::Result<Self> {
        Self::create_inner(limits, None)
    }

    /// Creates a job with `limits`, protected by `descriptor`.
    pub fn create_with_security(
        limits: &JobLimits,
        descriptor: &SecurityDescriptor,
    ) -> io::Result<Self> {
        Self::create_inner(limits, Some(descriptor))
    }

    fn create_inner(
        limits: &JobLimits,
        descriptor: Option<&SecurityDescriptor>,
    ) -> io::Result<Self> {
        limits.validate()?;
        let attributes = descriptor.map(|descriptor| descriptor.attributes(false));
        let attributes_pointer = attributes
            .as_ref()
            .map_or(null(), |attributes| attributes.as_ptr());
        // SAFETY: the attribute block, when present, and the descriptor it
        // points at outlive the call; no name is passed.
        let handle = unsafe { CreateJobObjectW(attributes_pointer, null()) };
        let job = Self(owned_from_creation(handle)?);
        let raw = limits.to_raw();
        // SAFETY: the job handle is live; the buffer pointer and length
        // describe exactly the local limit structure.
        let set = unsafe {
            SetInformationJobObject(
                job.raw(),
                JobObjectExtendedLimitInformation,
                (&raw as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),
                size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
            )
        };
        if set == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(job)
    }

    /// Assigns `process` to the job. The handle needs `PROCESS_SET_QUOTA`
    /// and `PROCESS_TERMINATE`, which a process this one created has.
    pub fn assign(&self, process: &impl AsHandle) -> io::Result<()> {
        let process = process.as_handle().as_raw_handle();
        // SAFETY: both handles are live for the call.
        if unsafe { AssignProcessToJobObject(self.raw(), process) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }

    /// Puts the calling process in the job and keeps the job handle open for
    /// the rest of its life. With [`JobLimits::kill_on_close`], every
    /// descendant then dies with this process, however it ends.
    pub fn assign_current_process(self) -> io::Result<()> {
        // SAFETY: the job handle is live; GetCurrentProcess returns a valid
        // pseudo-handle that does not need to be closed.
        if unsafe { AssignProcessToJobObject(self.raw(), current_process()) } == 0 {
            return Err(io::Error::last_os_error());
        }
        // The handle must outlive every process in the job, and this process
        // is one of them, so it is deliberately never closed.
        std::mem::forget(self);
        Ok(())
    }

    /// Terminates every process in the job with `exit_code`.
    pub fn terminate(&self, exit_code: u32) -> io::Result<()> {
        // SAFETY: the handle is live; the call takes no pointers.
        if unsafe { TerminateJobObject(self.raw(), exit_code) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }

    /// Reads the limits back from the kernel.
    pub fn limits(&self) -> io::Result<JobLimits> {
        let mut raw = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        // SAFETY: the handle is live; the buffer pointer and length describe
        // exactly the local limit structure and the returned-length pointer is
        // null, which the API permits.
        let queried = unsafe {
            QueryInformationJobObject(
                self.raw(),
                JobObjectExtendedLimitInformation,
                (&mut raw as *mut JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),
                size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
                null_mut(),
            )
        };
        if queried == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(JobLimits::from_raw(&raw))
    }

    fn raw(&self) -> RawHandle {
        self.0.as_raw_handle()
    }
}

impl AsHandle for Job {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

impl AsRawHandle for Job {
    fn as_raw_handle(&self) -> RawHandle {
        self.raw()
    }
}

impl From<Job> for OwnedHandle {
    fn from(job: Job) -> Self {
        job.0
    }
}

