        }
    }
}

//! Bounded storage for Win32 APIs that report a required byte count.
//!
//! Many Win32 queries are called twice: once with no buffer to learn the size,
//! then again with a buffer of that size. The size can change between the two
//! calls, and a hostile or buggy provider can report a length larger than the
//! buffer it was given. [`probe_word_aligned`] runs that protocol with a cap
//! on every length and exposes only the bytes the API reported writing.
#![allow(unsafe_code)]

use std::io;
use std::mem::{align_of, size_of};
use std::ptr::null_mut;

/// The result of one call that writes into a caller-owned buffer.
#[derive(Debug)]
pub(crate) enum CallOutcome {
    Complete,
    MoreData(io::Error),
}

/// A failure in the null-probe-then-fill protocol.
#[derive(Debug)]
pub(crate) enum ProbeError {
    Call(io::Error),
    ProbeCompleted(io::Error),
    SizeOutOfRange,
    FillNeedsMore(io::Error),
    ReturnedLengthOutOfRange,
}

impl ProbeError {
    /// Folds the protocol failure into an `io::Error`, naming `what` was read.
    pub(crate) fn into_io(self, what: &str) -> io::Error {
        match self {
            Self::Call(error) | Self::ProbeCompleted(error) | Self::FillNeedsMore(error) => error,
            Self::SizeOutOfRange => io::Error::new(
                io::ErrorKind::InvalidData,
                format!("{what} size is out of range"),
            ),
            Self::ReturnedLengthOutOfRange => io::Error::new(
                io::ErrorKind::InvalidData,
                format!("{what} changed during the read"),
            ),
        }
    }
}

/// Word-aligned storage whose logical length is the byte count reported by the
/// API, not the allocation's rounded byte capacity.
#[derive(Debug)]
pub(crate) struct WordAlignedBuffer {
    words: Vec<usize>,
    byte_length: usize,
}

impl WordAlignedBuffer {
    fn zeroed(byte_capacity: usize) -> Self {
        Self {
            words: vec![0_usize; byte_capacity.div_ceil(size_of::<usize>())],
            byte_length: byte_capacity,
        }
    }

    fn pointer(&mut self) -> *mut usize {
        if self.words.is_empty() {
            null_mut()
        } else {
            self.words.as_mut_ptr()
        }
    }

    pub(crate) fn len(&self) -> usize {
        self.byte_length
    }

    pub(crate) fn as_ptr(&self) -> *const u8 {
        self.words.as_ptr().cast()
    }

    fn supports<T>(&self) -> bool {
        align_of::<T>() <= align_of::<usize>() && self.byte_length >= size_of::<T>()
    }

    /// Reads a fixed header after the caller validates the byte representation.
    ///
    /// # Safety
    ///
    /// The reported bytes at the start of the buffer must form a valid `T`.
    pub(crate) unsafe fn read<T: Copy>(&self) -> Option<T> {
        if !self.supports::<T>() {
            return None;
        }
        // SAFETY: `words` supplies at least `usize` alignment, `supports`
        // checked T's alignment and complete byte range, and the caller
        // guarantees that those initialized bytes form a valid T.
        Some(unsafe { self.words.as_ptr().cast::<T>().read() })
    }
}

/// Calls an API first with a null buffer and then with word-aligned storage of
/// the size it asked for. No buffer is exposed unless the required and the
/// returned lengths both fall within `minimum_bytes..=maximum_bytes`.
pub(crate) fn probe_word_aligned(
    minimum_bytes: usize,
    maximum_bytes: usize,
    mut call: impl FnMut(*mut usize, u32, &mut u32) -> io::Result<CallOutcome>,
) -> Result<WordAlignedBuffer, ProbeError> {
    let maximum_bytes = maximum_bytes.min(u32::MAX as usize);
    let mut needed = 0_u32;
    match call(null_mut(), 0, &mut needed).map_err(ProbeError::Call)? {
        CallOutcome::Complete if needed == 0 && minimum_bytes == 0 => {
            return Ok(WordAlignedBuffer::zeroed(0));
        }
        CallOutcome::Complete => {
            return Err(ProbeError::ProbeCompleted(io::Error::last_os_error()));
        }
        CallOutcome::MoreData(_) => {}
    }

    let needed = needed as usize;
    if needed < minimum_bytes || needed > maximum_bytes {
        return Err(ProbeError::SizeOutOfRange);
    }

    // The allocation is zero-initialized, so rounded word padding and any
    // bytes the API does not overwrite never contain uninitialized data.
    let mut storage = WordAlignedBuffer::zeroed(needed);
    let capacity = needed as u32;
    let mut filled = capacity;
    match call(storage.pointer(), capacity, &mut filled).map_err(ProbeError::Call)? {
        CallOutcome::Complete => {}
        // A larger requirement after the probe is a two-call race; the short
        // allocation is discarded without exposing it.
        CallOutcome::MoreData(error) => return Err(ProbeError::FillNeedsMore(error)),
    }

    let filled = filled as usize;
    if filled < minimum_bytes || filled > needed {
        return Err(ProbeError::ReturnedLengthOutOfRange);
    }
    storage.byte_length = filled;
    Ok(storage)
}

#[cfg(test)]
mod tests {
    use std::io;
    use std::mem::{align_of, size_of};

    use super::{probe_word_aligned, CallOutcome, ProbeError};

    fn more_data() -> CallOutcome {
        CallOutcome::MoreData(io::Error::from_raw_os_error(234))
    }

    #[repr(C)]
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct Header {
        first: usize,
        second: u32,
    }

    #[test]
    fn the_fill_pointer_and_the_header_are_word_aligned() {
        let expected = Header {
            first: 0x1234,
            second: 0x5678,
        };
        let response = probe_word_aligned(
            size_of::<Header>(),
            size_of::<Header>(),
            |buffer, capacity, needed| {
                if buffer.is_null() {
                    *needed = size_of::<Header>() as u32;
                    return Ok(more_data());
                }
                assert_eq!((buffer as usize) % align_of::<usize>(), 0);
                assert_eq!(capacity as usize, size_of::<Header>());
                // SAFETY: the word-aligned allocation has room for Header.
                unsafe { buffer.cast::<Header>().write(expected) };
                Ok(CallOutcome::Complete)
            },
        )
        .unwrap();

        assert_eq!(response.len(), size_of::<Header>());
        // SAFETY: the fake API wrote `expected` as a complete Header.
        assert_eq!(unsafe { response.read::<Header>() }, Some(expected));
    }

    #[test]
    fn growth_between_the_two_calls_is_rejected() {
        let mut calls = 0;
        let error = probe_word_aligned(1, 64, |buffer, capacity, needed| {
            calls += 1;
            if buffer.is_null() {
                *needed = 8;
                return Ok(more_data());
            }
            assert_eq!(capacity, 8);
            *needed = 16;
            Ok(more_data())
        })
        .unwrap_err();

        assert_eq!(calls, 2);
        assert!(matches!(error, ProbeError::FillNeedsMore(_)));
    }

    #[test]
    fn the_caller_cap_is_enforced_before_allocation() {
        let error = probe_word_aligned(0, 4, |_, _, needed| {
            *needed = 5;
            Ok(more_data())
        })
        .unwrap_err();
        assert!(matches!(error, ProbeError::SizeOutOfRange));
    }

    #[test]
    fn an_api_cannot_report_more_bytes_than_it_was_given() {
        let error = probe_word_aligned(1, 64, |buffer, _, needed| {
            if buffer.is_null() {
                *needed = 8;
                return Ok(more_data());
            }
            *needed = 9;
            Ok(CallOutcome::Complete)
        })
        .unwrap_err();
        assert!(matches!(error, ProbeError::ReturnedLengthOutOfRange));
    }

    #[test]
    fn a_header_larger_than_the_reported_bytes_is_not_read() {
        let response = probe_word_aligned(1, 64, |buffer, _, needed| {
            if buffer.is_null() {
                *needed = 4;
                return Ok(more_data());
            }
            *needed = 4;
            Ok(CallOutcome::Complete)
        })
        .unwrap();
        // SAFETY: `read` refuses before touching memory because 4 bytes cannot
        // hold a Header.
        assert_eq!(unsafe { response.read::<Header>() }, None);
    }
}

//! Primary tokens for starting a child as another user or in another session.
#![allow(unsafe_code)]

use std::io;
use std::mem::size_of;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle, RawHandle};
use std::ptr::{null, null_mut};

use windows_sys::Win32::Security::{
    DuplicateTokenEx, GetTokenInformation, SecurityImpersonation, SetTokenInformation,
    TokenPrimary, TokenSessionId, TOKEN_ADJUST_DEFAULT, TOKEN_ADJUST_SESSIONID,
    TOKEN_ASSIGN_PRIMARY, TOKEN_DUPLICATE, TOKEN_QUERY,
};
use windows_sys::Win32::System::RemoteDesktop::WTSQueryUserToken;
use windows_sys::Win32::System::Threading::OpenProcessToken;

use crate::handle::{current_process, owned_from_creation};
use crate::process::token_is_elevated;

/// The rights every primary token here is opened or duplicated with: enough
/// to query it, start a process with it and move it to another session.
const PRIMARY_RIGHTS: u32 = TOKEN_QUERY
    | TOKEN_DUPLICATE
    | TOKEN_ASSIGN_PRIMARY
    | TOKEN_ADJUST_SESSIONID
    | TOKEN_ADJUST_DEFAULT;

/// A primary access token that [`crate::Launch::as_user`] can start a child
/// with.
#[derive(Debug)]
pub struct PrimaryToken(OwnedHandle);

impl PrimaryToken {
    /// A primary copy of this process's own token.
    ///
    /// A service running as LocalSystem uses this, followed by
    /// [`set_session_id`](Self::set_session_id), to start a helper as
    /// LocalSystem on an interactive user's desktop.
    pub fn duplicate_current_process() -> io::Result<Self> {
        let mut own = null_mut();
        // SAFETY: the process pseudo-handle is always valid and `own` is a
        // local out pointer whose handle is owned immediately below.
        if unsafe { OpenProcessToken(current_process(), TOKEN_QUERY | TOKEN_DUPLICATE, &mut own) }
            == 0
        {
            return Err(io::Error::last_os_error());
        }
        let own = owned_from_creation(own)?;
        let mut duplicate = null_mut();
        // SAFETY: `own` is a live token opened with TOKEN_DUPLICATE; no
        // security attributes are passed and `duplicate` is a local out value.
        let duplicated = unsafe {
            DuplicateTokenEx(
                own.as_raw_handle(),
                PRIMARY_RIGHTS,
                null(),
                SecurityImpersonation,
                TokenPrimary,
                &mut duplicate,
            )
        };
        if duplicated == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Self(owned_from_creation(duplicate)?))
    }

    /// The primary token of the user logged on to `session_id`, through
    /// `WTSQueryUserToken`.
    ///
    /// Only a LocalSystem caller holding `SeTcbPrivilege` can do this; anyone
    /// else gets `ERROR_PRIVILEGE_NOT_HELD` (1314). A session with no logged-on
    /// user reports `ERROR_NO_TOKEN` (1008).
    pub fn for_session_user(session_id: u32) -> io::Result<Self> {
        let mut token = null_mut();
        // SAFETY: plain integer in, local out pointer whose handle is owned
        // immediately below.
        if unsafe { WTSQueryUserToken(session_id, &mut token) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Self(owned_from_creation(token)?))
    }

    /// The Terminal Services session a process started with this token runs
    /// in.
    pub fn session_id(&self) -> io::Result<u32> {
        let mut session = 0_u32;
        let mut returned = 0_u32;
        // SAFETY: the token is live; the buffer pointer and length describe
        // exactly the local `u32`.
        let queried = unsafe {
            GetTokenInformation(
                self.raw(),
                TokenSessionId,
                (&mut session as *mut u32).cast(),
                size_of::<u32>() as u32,
                &mut returned,
            )
        };
        if queried == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(session)
    }

    /// Moves the token to `session_id`, so a child started with it appears in
    /// that session.
    ///
    /// Windows requires `SeTcbPrivilege` enabled in the caller's token, which
    /// in practice means a LocalSystem service. Anyone else gets
    /// `ERROR_PRIVILEGE_NOT_HELD` (1314).
    pub fn set_session_id(&mut self, session_id: u32) -> io::Result<()> {
        // SAFETY: the token is live and was opened with
        // TOKEN_ADJUST_SESSIONID | TOKEN_ADJUST_DEFAULT; the buffer pointer and
        // length describe exactly the local `u32`.
        let set = unsafe {
            SetTokenInformation(
                self.raw(),
                TokenSessionId,
                (&session_id as *const u32).cast(),
                size_of::<u32>() as u32,
            )
        };
        if set == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }

    /// Whether the token is elevated (a full administrator token).
    pub fn is_elevated(&self) -> io::Result<bool> {
        token_is_elevated(self.raw())
    }

    fn raw(&self) -> RawHandle {
        self.0.as_raw_handle()
    }
}

impl AsHandle for PrimaryToken {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

impl AsRawHandle for PrimaryToken {
    fn as_raw_handle(&self) -> RawHandle {
        self.raw()
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use windows_sys::Win32::Foundation::{ERROR_NO_TOKEN, ERROR_PRIVILEGE_NOT_HELD};

    use super::PrimaryToken;
    use crate::handle::WaitOutcome;
    use crate::job::{Job, JobLimits};
    use crate::launch::Launch;
    use crate::session::current_session_id;

    fn cmd() -> std::path::PathBuf {
        let root = std::env::var_os("SystemRoot").expect("SystemRoot is set");
        std::path::Path::new(&root).join("System32").join("cmd.exe")
    }

    fn running_as_system() -> bool {
        crate::security::current_user_sid_string().unwrap() == "S-1-5-18"
    }

    #[test]
    fn a_duplicate_of_the_own_token_stays_in_the_current_session() {
        let token = [REDACTED];
        assert_eq!(token.session_id().unwrap(), current_session_id().unwrap());
        assert_eq!(
            token.is_elevated().unwrap(),
            crate::process::is_elevated().unwrap()
        );
    }

    #[test]
    fn moving_a_token_needs_tcb_unless_running_as_system() {
        let mut token = [REDACTED];
        let session = token.session_id().unwrap();
        match token.set_session_id(session) {
            Ok(()) => assert!(running_as_system()),
            Err(error) => {
                assert!(!running_as_system());
                assert_eq!(error.raw_os_error(), Some(ERROR_PRIVILEGE_NOT_HELD as i32));
            }
        }
    }

    #[test]
    fn querying_a_session_user_needs_tcb_unless_running_as_system() {
        let session = current_session_id().unwrap();
        match PrimaryToken:[REDACTED] {
            Ok(token) => {
                assert!(running_as_system());
                assert_eq!(token.session_id().unwrap(), session);
            }
            Err(error) if running_as_system() => {
                assert_eq!(error.raw_os_error(), Some(ERROR_NO_TOKEN as i32));
            }
            Err(error) => {
                assert_eq!(error.raw_os_error(), Some(ERROR_PRIVILEGE_NOT_HELD as i32));
            }
        }
    }

    #[test]
    fn a_child_started_with_the_own_token_runs_and_exits() {
        let token = [REDACTED];
        let job = Job::create(&JobLimits::new().kill_on_close(true)).unwrap();
        let child = Launch::new(cmd())
            .args(["/d", "/c", "exit 9"])
            .as_user(&token)
            .spawn_in_job(&job)
            .unwrap();
        assert_eq!(
            child.wait(Some(Duration::from_secs(30))).unwrap(),
            WaitOutcome::Signaled
        );
        assert_eq!(child.exit_code().unwrap(), Some(9));
    }
}

//! Named pipes whose every operation has a deadline and can end early when
//! the peer process exits.
#![allow(unsafe_code)]

use std::fmt;
use std::fs::{File, OpenOptions};
use std::io;
use std::os::windows::fs::OpenOptionsExt;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle, RawHandle};
use std::ptr::null_mut;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use windows_sys::Win32::Foundation::{
    ERROR_FILE_NOT_FOUND, ERROR_IO_PENDING, ERROR_NOT_FOUND, ERROR_PIPE_BUSY, ERROR_PIPE_CONNECTED,
    HANDLE, STATUS_PENDING, TRUE, WAIT_TIMEOUT,
};
use windows_sys::Win32::Storage::FileSystem::{
    ReadFile, WriteFile, FILE_FLAG_FIRST_PIPE_INSTANCE, FILE_FLAG_OVERLAPPED, PIPE_ACCESS_DUPLEX,
    PIPE_ACCESS_INBOUND, PIPE_ACCESS_OUTBOUND, SECURITY_IDENTIFICATION, SECURITY_SQOS_PRESENT,
};
use windows_sys::Win32::System::Pipes::{
    ConnectNamedPipe, CreateNamedPipeW, DisconnectNamedPipe, GetNamedPipeClientProcessId,
    GetNamedPipeServerProcessId, PIPE_READMODE_BYTE, PIPE_REJECT_REMOTE_CLIENTS, PIPE_TYPE_BYTE,
};
use windows_sys::Win32::System::IO::{
    CancelIoEx, GetOverlappedResult, GetOverlappedResultEx, OVERLAPPED,
};

use crate::event::ManualResetEvent;
use crate::handle::{owned_from_creation, wait, WaitOutcome};
use crate::security::SecurityDescriptor;
use crate::wide::wide_null;

const LOCAL_PIPE_PREFIX: &str = r"\\.\pipe\";
const DEFAULT_BUFFER_BYTES: u32 = 64 * 1024;

static CANCELLED_OPERATIONS: AtomicU64 = AtomicU64::new(0);

/// How long a pipe operation may take, and whose exit ends it early.
#[derive(Clone, Copy, Debug)]
pub struct PipeWait<'a> {
    /// The operation fails with [`PipeError::TimedOut`] once this passes.
    pub deadline: Instant,
    /// Each kernel wait is at most this long; the peer and the deadline are
    /// checked between slices.
    pub poll: Duration,
    /// A process (or any waitable object) whose signal aborts the operation
    /// with [`PipeError::PeerExited`].
    pub peer: Option<BorrowedHandle<'a>>,
}

impl<'a> PipeWait<'a> {
    /// Waits until `deadline`, checking every 10 ms, with no peer.
    pub fn until(deadline: Instant) -> Self {
        Self {
            deadline,
            poll: Duration::from_millis(10),
            peer: None,
        }
    }

    /// Waits for at most `timeout` from now, checking every 10 ms, with no
    /// peer.
    pub fn within(timeout: Duration) -> Self {
        Self::until(Instant::now() + timeout)
    }

    /// Also ends the operation when `peer` is signaled, typically the
    /// process on the other end.
    #[must_use]
    pub fn with_peer<H: AsHandle + ?Sized>(mut self, peer: &'a H) -> Self {
        self.peer = Some(peer.as_handle());
        self
    }
}

/// A failure from a deadline-bound pipe operation.
#[derive(Debug)]
#[non_exhaustive]
pub enum PipeError {
    /// The peer was signaled before the operation completed.
    PeerExited,
    /// The deadline passed before the operation completed.
    TimedOut,
    /// Checking the peer failed.
    PeerCheck(io::Error),
    /// The operation itself failed with this Win32 error.
    Io(io::Error),
    /// A write transferred no bytes.
    NoProgress,
    /// Cancelling a pending operation failed after the operation was reaped.
    Cancel(io::Error),
}

impl fmt::Display for PipeError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PeerExited => formatter.write_str("the peer process exited"),
            Self::TimedOut => formatter.write_str("the operation timed out"),
            Self::PeerCheck(error) => write!(formatter, "checking the peer failed: {error}"),
            Self::Io(error) => error.fmt(formatter),
            Self::NoProgress => formatter.write_str("the pipe accepted no bytes"),
            Self::Cancel(error) => {
                write!(
                    formatter,
                    "cancelling the pending operation failed: {error}"
                )
            }
        }
    }
}

impl std::error::Error for PipeError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::PeerCheck(error) | Self::Io(error) | Self::Cancel(error) => Some(error),
            Self::PeerExited | Self::TimedOut | Self::NoProgress => None,
        }
    }
}

impl From<PipeError> for io::Error {
    fn from(error: PipeError) -> Self {
        match error {
            PipeError::Io(error) => error,
            PipeError::TimedOut => io::Error::new(io::ErrorKind::TimedOut, error),
            other => io::Error::other(other),
        }
    }
}

/// The direction data flows, seen from the server.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PipeDirection {
    /// The client writes, the server reads.
    Inbound,
    /// The server writes, the client reads.
    Outbound,
    /// Both sides read and write.
    Duplex,
}

/// The access a [`PipeClient`] opens the pipe with.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PipeAccess {
    /// Read only.
    Read,
    /// Write only.
    Write,
    /// Read and write.
    ReadWrite,
}

/// A single-instance, local-only byte pipe server.
///
/// The pipe is created with `FILE_FLAG_FIRST_PIPE_INSTANCE`, so creation
/// fails instead of attaching to a pipe some other process already created
/// under the same name, and with `PIPE_REJECT_REMOTE_CLIENTS`. Its access is
/// whatever the [`SecurityDescriptor`] grants.
#[derive(Debug)]
pub struct PipeServer(OwnedHandle);

impl PipeServer {
    /// Creates `name` (which must start with `\\.\pipe\`) with 64 KiB
    /// buffers.
    pub fn create(
        name: &str,
        direction: PipeDirection,
        descriptor: &SecurityDescriptor,
    ) -> io::Result<Self> {
        Self::create_with_buffers(
            name,
            direction,
            descriptor,
            DEFAULT_BUFFER_BYTES,
            DEFAULT_BUFFER_BYTES,
        )
    }

    /// Creates `name` with the given outbound and inbound buffer sizes. The
    /// sizes are advisory; Windows may round them.
    pub fn create_with_buffers(
        name: &str,
        direction: PipeDirection,
        descriptor: &SecurityDescriptor,
        out_buffer_bytes: u32,
        in_buffer_bytes: u32,
    ) -> io::Result<Self> {
        let name = local_pipe_name(name)?;
        let attributes = descriptor.attributes(false);
        let access = match direction {
            PipeDirection::Inbound => PIPE_ACCESS_INBOUND,
            PipeDirection::Outbound => PIPE_ACCESS_OUTBOUND,
            PipeDirection::Duplex => PIPE_ACCESS_DUPLEX,
        };
        // SAFETY: `name` is NUL-terminated and the borrowed security attributes
        // and descriptor remain live until CreateNamedPipeW returns.
        let handle = unsafe {
            CreateNamedPipeW(
                name.as_ptr(),
                access | FILE_FLAG_FIRST_PIPE_INSTANCE | FILE_FLAG_OVERLAPPED,
                PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_REJECT_REMOTE_CLIENTS,
                1,
                out_buffer_bytes,
                in_buffer_bytes,
                0,
                attributes.as_ptr(),
            )
        };
        Ok(Self(owned_from_creation(handle)?))
    }

    /// Waits for a client to connect.
    pub fn connect(&self, wait: &PipeWait<'_>) -> Result<(), PipeError> {
        let event = ManualResetEvent::new().map_err(PipeError::Io)?;
        let mut overlapped = new_overlapped(&event);
        // SAFETY: the server handle was opened for overlapped I/O; `overlapped`
        // and its event stay alive through synchronous completion or wait/reap.
        if unsafe { ConnectNamedPipe(self.raw(), &mut overlapped) } != 0 {
            return Ok(());
        }
        let error = io::Error::last_os_error();
        match win32_code(&error) {
            Some(ERROR_PIPE_CONNECTED) => Ok(()),
            Some(ERROR_IO_PENDING) => wait_for_overlapped(self.raw(), &overlapped, wait).map(drop),
            _ => Err(PipeError::Io(error)),
        }
    }

    /// Drops the connected client, so the next [`connect`](Self::connect)
    /// can accept another.
    pub fn disconnect(&self) -> io::Result<()> {
        // SAFETY: the handle is live; the call takes no pointers.
        if unsafe { DisconnectNamedPipe(self.raw()) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }

    /// The process ID of the connected client, as the kernel recorded it.
    /// Compare it with the PID of the child you started before trusting what
    /// the client sends.
    pub fn client_process_id(&self) -> io::Result<u32> {
        let mut pid = 0;
        // SAFETY: the server owns a live named-pipe handle and `pid` is a local
        // output that remains valid for the call.
        if unsafe { GetNamedPipeClientProcessId(self.raw(), &mut pid) } == 0 {
            return Err(io::Error::last_os_error());
        }
        nonzero_pid(pid, "client")
    }

    /// Writes all of `bytes`.
    pub fn write_all(&self, bytes: &[u8], wait: &PipeWait<'_>) -> Result<(), PipeError> {
        write_all_overlapped(self.raw(), bytes, wait)
    }

    /// Reads into `buffer`, returning the byte count.
    pub fn read(&self, buffer: &mut [u8], wait: &PipeWait<'_>) -> Result<usize, PipeError> {
        read_overlapped(self.raw(), buffer, wait)
    }

    fn raw(&self) -> HANDLE {
        self.0.as_raw_handle()
    }
}

impl AsHandle for PipeServer {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

impl AsRawHandle for PipeServer {
    fn as_raw_handle(&self) -> RawHandle {
        self.raw()
    }
}

/// A client connection to a local named pipe.
///
/// The pipe is opened with `SECURITY_IDENTIFICATION`, so the server can learn
/// who the client is but cannot act as the client.
#[derive(Debug)]
pub struct PipeClient(File);

impl PipeClient {
    /// Opens `name` (which must start with `\\.\pipe\`), retrying every
    /// `poll` while the pipe does not exist yet or is busy, until `deadline`.
    pub fn open(
        name: &str,
        access: PipeAccess,
        deadline: Instant,
        poll: Duration,
    ) -> Result<Self, PipeError> {
        local_pipe_name(name).map_err(PipeError::Io)?;
        loop {
            let mut options = OpenOptions::new();
            match access {
                PipeAccess::Read => options.read(true),
                PipeAccess::Write => options.write(true),
                PipeAccess::ReadWrite => options.read(true).write(true),
            };
            options.custom_flags(
                FILE_FLAG_OVERLAPPED | SECURITY_SQOS_PRESENT | SECURITY_IDENTIFICATION,
            );
            match options.open(name) {
                Ok(file) => return Ok(Self(file)),
                Err(error)
                    if matches!(
                        win32_code(&error),
                        Some(ERROR_FILE_NOT_FOUND | ERROR_PIPE_BUSY)
                    ) =>
                {
                    let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
                        return Err(PipeError::TimedOut);
                    };
                    std::thread::sleep(remaining.min(poll));
                }
                Err(error) => return Err(PipeError::Io(error)),
            }
        }
    }

    /// The process ID of the server, as the kernel recorded it. Compare it
    /// with the process you expect before trusting what the server sends.
    pub fn server_process_id(&self) -> io::Result<u32> {
        let mut pid = 0;
        // SAFETY: the client owns a live named-pipe handle; `pid` is a local
        // out value.
        if unsafe { GetNamedPipeServerProcessId(self.0.as_raw_handle(), &mut pid) } == 0 {
            return Err(io::Error::last_os_error());
        }
        nonzero_pid(pid, "server")
    }

    /// Reads into `buffer`, returning the byte count.
    pub fn read(&self, buffer: &mut [u8], wait: &PipeWait<'_>) -> Result<usize, PipeError> {
        read_overlapped(self.0.as_raw_handle(), buffer, wait)
    }

    /// Writes all of `bytes`.
    pub fn write_all(&self, bytes: &[u8], wait: &PipeWait<'_>) -> Result<(), PipeError> {
        write_all_overlapped(self.0.as_raw_handle(), bytes, wait)
    }
}

impl AsHandle for PipeClient {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

impl AsRawHandle for PipeClient {
    fn as_raw_handle(&self) -> RawHandle {
        self.0.as_raw_handle()
    }
}

fn local_pipe_name(name: &str) -> io::Result<Vec<u16>> {
    let is_local = name
        .get(..LOCAL_PIPE_PREFIX.len())
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case(LOCAL_PIPE_PREFIX));
    if !is_local || name.len() == LOCAL_PIPE_PREFIX.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            r"pipe names must start with \\.\pipe\ and name a pipe",
        ));
    }
    wide_null(name)
}

fn nonzero_pid(pid: u32, side: &str) -> io::Result<u32> {
    if pid == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("the named pipe {side} reported process ID zero"),
        ));
    }
    Ok(pid)
}

fn new_overlapped(event: &ManualResetEvent) -> OVERLAPPED {
    OVERLAPPED {
        hEvent: event.as_raw(),
        ..Default::default()
    }
}

fn read_overlapped(
    handle: HANDLE,
    buffer: &mut [u8],
    wait: &PipeWait<'_>,
) -> Result<usize, PipeError> {
    let event = ManualResetEvent::new().map_err(PipeError::Io)?;
    let mut overlapped = new_overlapped(&event);
    let request = buffer.len().min(u32::MAX as usize) as u32;
    // SAFETY: `handle` is a live pipe opened for overlapped I/O; `buffer` is
    // writable for `request` bytes; the OVERLAPPED and its event stay alive
    // through synchronous completion or wait/reap. The byte-count pointer is
    // null as required for asynchronous handles.
    let completed = unsafe {
        ReadFile(
            handle,
            buffer.as_mut_ptr(),
            request,
            null_mut(),
            &mut overlapped,
        )
    };
    let read = if completed != 0 {
        completed_overlapped_result(handle, &overlapped)?
    } else {
        let error = io::Error::last_os_error();
        if win32_code(&error) != Some(ERROR_IO_PENDING) {
            return Err(PipeError::Io(error));
        }
        wait_for_overlapped(handle, &overlapped, wait)?
    };
    Ok((read as usize).min(request as usize))
}

fn write_all_overlapped(
    handle: HANDLE,
    mut bytes: &[u8],
    wait: &PipeWait<'_>,
) -> Result<(), PipeError> {
    while !bytes.is_empty() {
        let request = bytes.len().min(u32::MAX as usize);
        let event = ManualResetEvent::new().map_err(PipeError::Io)?;
        let mut overlapped = new_overlapped(&event);
        // SAFETY: `handle` is a live pipe opened for overlapped I/O; `bytes` is
        // readable for `request` bytes; the OVERLAPPED and its event stay alive
        // through synchronous completion or wait/reap. The byte-count pointer
        // is null as required for asynchronous handles.
        let completed = unsafe {
            WriteFile(
                handle,
                bytes.as_ptr(),
                request as u32,
                null_mut(),
                &mut overlapped,
            )
        };
        let written = if completed != 0 {
            completed_overlapped_result(handle, &overlapped)?
        } else {
            let error = io::Error::last_os_error();
            if win32_code(&error) != Some(ERROR_IO_PENDING) {
                return Err(PipeError::Io(error));
            }
            wait_for_overlapped(handle, &overlapped, wait)?
        };
        if written == 0 {
            return Err(PipeError::NoProgress);
        }
        bytes = &bytes[(written as usize).min(request)..];
    }
    Ok(())
}

fn completed_overlapped_result(handle: HANDLE, overlapped: &OVERLAPPED) -> Result<u32, PipeError> {
    let mut transferred = 0;
    // SAFETY: the operation reported synchronous completion; `handle` and its
    // unique OVERLAPPED remain live while the completed byte count is queried.
    if unsafe { GetOverlappedResult(handle, overlapped, &mut transferred, 0) } == 0 {
        return Err(PipeError::Io(io::Error::last_os_error()));
    }
    Ok(transferred)
}

fn wait_for_overlapped(
    handle: HANDLE,
    overlapped: &OVERLAPPED,
    pipe_wait: &PipeWait<'_>,
) -> Result<u32, PipeError> {
    loop {
        if let Some(peer) = pipe_wait.peer {
            match wait(&peer, Some(Duration::ZERO)) {
                Ok(WaitOutcome::Signaled) => {
                    return cancel_and_reap(handle, overlapped, PipeError::PeerExited);
                }
                Ok(WaitOutcome::TimedOut) => {}
                Ok(WaitOutcome::Abandoned) => {
                    let error = io::Error::other("the peer wait was abandoned");
                    return cancel_and_reap(handle, overlapped, PipeError::PeerCheck(error));
                }
                Err(error) => {
                    return cancel_and_reap(handle, overlapped, PipeError::PeerCheck(error));
                }
            }
        }
        let Some(remaining) = pipe_wait.deadline.checked_duration_since(Instant::now()) else {
            return cancel_and_reap(handle, overlapped, PipeError::TimedOut);
        };
        let slice_milliseconds = remaining
            .min(pipe_wait.poll)
            .as_millis()
            .clamp(1, u128::from(u32::MAX - 1)) as u32;
        let mut transferred = 0;
        // SAFETY: `handle` is live; `overlapped` and its event remain live until
        // this operation completes or is cancelled and reaped; `transferred` is
        // a local output.
        let finished = unsafe {
            GetOverlappedResultEx(handle, overlapped, &mut transferred, slice_milliseconds, 0)
        };
        if finished != 0 {
            return Ok(transferred);
        }
        let error = io::Error::last_os_error();
        if win32_code(&error) == Some(WAIT_TIMEOUT) {
            continue;
        }
        if overlapped_has_completed(overlapped) {
            // The operation finished with this error (a broken pipe, an
            // abort); there is nothing left to cancel or reap.
            return Err(PipeError::Io(error));
        }
        return cancel_and_reap(handle, overlapped, PipeError::Io(error));
    }
}

/// `HasOverlappedIoCompleted`: the kernel replaces the pending status once the
/// operation has finished, whatever its outcome.
fn overlapped_has_completed(overlapped: &OVERLAPPED) -> bool {
    overlapped.Internal != STATUS_PENDING as usize
}

fn cancel_and_reap(
    handle: HANDLE,
    overlapped: &OVERLAPPED,
    original: PipeError,
) -> Result<u32, PipeError> {
    CANCELLED_OPERATIONS.fetch_add(1, Ordering::Relaxed);
    // SAFETY: `handle` is live and `overlapped` names the pending operation
    // that this function always reaps before either value can cease to be
    // valid.
    let cancellation = unsafe { CancelIoEx(handle, overlapped) };
    let cancellation_error = if cancellation == 0 {
        let error = io::Error::last_os_error();
        (win32_code(&error) != Some(ERROR_NOT_FOUND)).then_some(error)
    } else {
        None
    };
    let mut transferred = 0;
    // SAFETY: the same live handle and OVERLAPPED are retained after
    // cancellation; waiting here completes the mandatory reap before their
    // backing storage drops.
    unsafe { GetOverlappedResult(handle, overlapped, &mut transferred, TRUE) };
    match cancellation_error {
        Some(error) => Err(PipeError::Cancel(error)),
        None => Err(original),
    }
}

fn win32_code(error: &io::Error) -> Option<u32> {
    error.raw_os_error().map(|code| code as u32)
}

#[cfg(test)]
fn cancelled_operations() -> u64 {
    CANCELLED_OPERATIONS.load(Ordering::Relaxed)
}

#[cfg(test)]
mod tests {
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::sync::Mutex;
    use std::time::{Duration, Instant};

    use super::{
        cancelled_operations, PipeAccess, PipeClient, PipeDirection, PipeError, PipeServer,
        PipeWait,
    };
    use crate::process::Process;
    use crate::security::SecurityDescriptor;

    static NEXT_NONCE: AtomicU64 = AtomicU64::new(0);
    static SERIAL: Mutex<()> = Mutex::new(());

    fn pipe_name() -> String {
        format!(
            r"\\.\pipe\win-custody-tests-{}-{}",
            std::process::id(),
            NEXT_NONCE.fetch_add(1, Ordering::Relaxed)
        )
    }

    fn descriptor() -> SecurityDescriptor {
        SecurityDescriptor::from_sddl("D:P(A;;GA;;;SY)(A;;GA;;;BA)(A;;GA;;;OW)").unwrap()
    }

    fn pattern(length: usize, modulus: usize) -> Vec<u8> {
        (0..length).map(|index| (index % modulus) as u8).collect()
    }

    #[test]
    fn non_local_names_are_rejected() {
        for name in [r"\\server\pipe\x", r"\\.\pipe\", "plain"] {
            let error =
                PipeServer::create(name, PipeDirection::Inbound, &descriptor()).unwrap_err();
            assert_eq!(error.kind(), std::io::ErrorKind::InvalidInput);
        }
    }

    #[test]
    fn a_second_server_with_the_same_name_is_refused() {
        let name = pipe_name();
        let _first = PipeServer::create(&name, PipeDirection::Inbound, &descriptor()).unwrap();
        assert!(PipeServer::create(&name, PipeDirection::Inbound, &descriptor()).is_err());
    }

    #[test]
    fn an_outbound_server_transfers_a_large_stream_and_sees_the_client_pid() {
        let _serial = SERIAL.lock().unwrap();
        let name = pipe_name();
        let server = PipeServer::create(&name, PipeDirection::Outbound, &descriptor()).unwrap();
        let expected = pattern(200 * 1024, 251);
        let client_name = name.clone();
        let client = std::thread::spawn(move || {
            let client = PipeClient::open(
                &client_name,
                PipeAccess::Read,
                Instant::now() + Duration::from_secs(5),
                Duration::from_millis(5),
            )
            .unwrap();
            assert_eq!(client.server_process_id().unwrap(), std::process::id());
            let mut received = Vec::new();
            let mut chunk = vec![0_u8; 64 * 1024];
            while received.len() < 200 * 1024 {
                let read = client
                    .read(&mut chunk, &PipeWait::within(Duration::from_secs(5)))
                    .unwrap();
                if read == 0 {
                    break;
                }
                received.extend_from_slice(&chunk[..read]);
            }
            received
        });
        server
            .connect(&PipeWait::within(Duration::from_secs(5)))
            .unwrap();
        assert_eq!(server.client_process_id().unwrap(), std::process::id());
        server
            .write_all(&expected, &PipeWait::within(Duration::from_secs(5)))
            .unwrap();
        assert_eq!(client.join().unwrap(), expected);
    }

    #[test]
    fn a_duplex_pipe_carries_a_request_and_a_reply() {
        let _serial = SERIAL.lock().unwrap();
        let name = pipe_name();
        let server = PipeServer::create(&name, PipeDirection::Duplex, &descriptor()).unwrap();
        let client_name = name.clone();
        let client = std::thread::spawn(move || {
            let client = PipeClient::open(
                &client_name,
                PipeAccess::ReadWrite,
                Instant::now() + Duration::from_secs(5),
                Duration::from_millis(5),
            )
            .unwrap();
            let wait = PipeWait::within(Duration::from_secs(5));
            client.write_all(b"ping", &wait).unwrap();
            let mut reply = [0_u8; 4];
            let read = client.read(&mut reply, &wait).unwrap();
            reply[..read].to_vec()
        });
        let wait = PipeWait::within(Duration::from_secs(5));
        server.connect(&wait).unwrap();
        let mut request = [0_u8; 4];
        let read = server.read(&mut request, &wait).unwrap();
        assert_eq!(&request[..read], b"ping");
        server.write_all(b"pong", &wait).unwrap();
        assert_eq!(client.join().unwrap(), b"pong");
    }

    #[test]
    fn a_connect_past_its_deadline_is_cancelled_and_reaped_once() {
        let _serial = SERIAL.lock().unwrap();
        let server =
            PipeServer::create(&pipe_name(), PipeDirection::Outbound, &descriptor()).unwrap();
        let before = cancelled_operations();
        let result = server.connect(&PipeWait {
            deadline: Instant::now() + Duration::from_millis(25),
            poll: Duration::from_millis(5),
            peer: None,
        });
        assert!(matches!(result, Err(PipeError::TimedOut)));
        assert_eq!(cancelled_operations(), before + 1);
    }

    #[test]
    fn an_exited_peer_ends_a_connect_early() {
        let _serial = SERIAL.lock().unwrap();
        let mut child = std::process::Command::new("cmd")
            .args(["/d", "/c", "exit 0"])
            .spawn()
            .unwrap();
        child.wait().unwrap();
        let peer = Process::from_child(&child).unwrap();
        let server =
            PipeServer::create(&pipe_name(), PipeDirection::Outbound, &descriptor()).unwrap();
        let before = cancelled_operations();
        let result = server.connect(&PipeWait::within(Duration::from_secs(5)).with_peer(&peer));
        assert!(matches!(result, Err(PipeError::PeerExited)));
        assert_eq!(cancelled_operations(), before + 1);
    }
}

//! Process handles with a fixed rights set, and elevation.
#![allow(unsafe_code)]

use std::ffi::{OsStr, OsString};
use std::io;
use std::mem::size_of;
use std::os::windows::ffi::OsStringExt;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle, RawHandle};
use std::path::{Path, PathBuf};
use std::ptr;
use std::time::Duration;

use windows_sys::Win32::Foundation::{
    DuplicateHandle, DUPLICATE_SAME_ACCESS, FILETIME, STILL_ACTIVE,
};
use windows_sys::Win32::Security::{
    GetTokenInformation, TokenElevation, TOKEN_ELEVATION, TOKEN_QUERY,
};
use windows_sys::Win32::Storage::FileSystem::SYNCHRONIZE;
use windows_sys::Win32::System::Threading::{
    GetExitCodeProcess, GetProcessId, GetProcessTimes, OpenProcess, OpenProcessToken,
    QueryFullProcessImageNameW, TerminateProcess, PROCESS_NAME_WIN32,
    PROCESS_QUERY_LIMITED_INFORMATION, PROCESS_TERMINATE,
};
use windows_sys::Win32::UI::Shell::{ShellExecuteExW, SEE_MASK_NOCLOSEPROCESS, SHELLEXECUTEINFOW};
use windows_sys::Win32::UI::WindowsAndMessaging::SW_HIDE;

use crate::handle::{current_process, owned_from_creation, wait, WaitOutcome};
use crate::launch::command_line_tail;
use crate::wide::wide_null;

const MAX_IMAGE_PATH_UNITS: usize = 32_768;

/// The rights a [`Process`] handle carries.
///
/// Each variant is a fixed rights set. [`Process::open`] cannot request
/// [`ProcessAccess::AsCreated`]: full access is only available on a process
/// this one created, so a reused PID can never be reopened with it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum ProcessAccess {
    /// `PROCESS_QUERY_LIMITED_INFORMATION`: identity and exit-code queries.
    QueryLimited,
    /// `SYNCHRONIZE`: waiting for exit.
    Synchronize,
    /// Identity queries and waiting for exit.
    QueryLimitedAndSynchronize,
    /// Identity queries, waiting for exit, and `PROCESS_TERMINATE`.
    Terminate,
    /// The rights the creating call granted: everything.
    AsCreated,
}

impl ProcessAccess {
    fn rights(self) -> u32 {
        match self {
            Self::QueryLimited => PROCESS_QUERY_LIMITED_INFORMATION,
            Self::Synchronize => SYNCHRONIZE,
            Self::QueryLimitedAndSynchronize => PROCESS_QUERY_LIMITED_INFORMATION | SYNCHRONIZE,
            Self::Terminate => PROCESS_QUERY_LIMITED_INFORMATION | SYNCHRONIZE | PROCESS_TERMINATE,
            Self::AsCreated => 0,
        }
    }
}

/// An open process handle with a fixed rights set.
///
/// The handle names one process object for its whole life, so unlike a PID
/// it cannot start pointing at an unrelated process after the original exits.
#[derive(Debug)]
pub struct Process {
    handle: OwnedHandle,
    access: ProcessAccess,
}

impl Process {
    /// Opens `pid` with exactly `access`. The error carries the Win32 code; a
    /// PID that has left the process table reports `ERROR_INVALID_PARAMETER`.
    pub fn open(pid: u32, access: ProcessAccess) -> io::Result<Self> {
        if access == ProcessAccess::AsCreated {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "full access is only available on a process this one created",
            ));
        }
        // SAFETY: OpenProcess takes plain integers and returns a new handle or
        // null; no memory is shared with the callee.
        let handle = unsafe { OpenProcess(access.rights(), 0, pid) };
        Ok(Self {
            handle: owned_from_creation(handle)?,
            access,
        })
    }

    /// Duplicates the handle `std` holds for `child`. The result keeps every
    /// right `CreateProcess` granted (job assignment and termination among
    /// them, which a reopen by PID would not get).
    pub fn from_child(child: &std::process::Child) -> io::Result<Self> {
        let mut duplicate = ptr::null_mut();
        // SAFETY: the source handle is the live one `child` owns for the
        // duration of this call, both process arguments are the current
        // process pseudo-handle, and `duplicate` is a local out value.
        let duplicated = unsafe {
            DuplicateHandle(
                current_process(),
                child.as_raw_handle(),
                current_process(),
                &mut duplicate,
                0,
                0,
                DUPLICATE_SAME_ACCESS,
            )
        };
        if duplicated == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Self {
            handle: owned_from_creation(duplicate)?,
            access: ProcessAccess::AsCreated,
        })
    }

    /// Starts `executable` through the shell's `runas` verb, which shows the
    /// elevation prompt, and returns the process the shell created.
    ///
    /// Each argument is quoted the way `CommandLineToArgvW` parses it, so it
    /// reaches the child unchanged. The child's window starts hidden. A user
    /// who declines the prompt makes this fail with `ERROR_CANCELLED` (1223)
    /// as the Win32 code.
    ///
    /// The shell may need COM: call this from a thread that has initialized
    /// COM if the target is not a plain executable.
    pub fn launch_elevated<I, S>(executable: &Path, arguments: I) -> io::Result<Self>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        let arguments: Vec<OsString> = arguments
            .into_iter()
            .map(|argument| argument.as_ref().to_owned())
            .collect();
        let verb = wide_null("runas")?;
        let file = wide_null(executable)?;
        let parameters = command_line_tail(&arguments)?;
        let mut info = SHELLEXECUTEINFOW {
            cbSize: size_of::<SHELLEXECUTEINFOW>() as u32,
            fMask: SEE_MASK_NOCLOSEPROCESS,
            lpVerb: verb.as_ptr(),
            lpFile: file.as_ptr(),
            lpParameters: parameters.as_ptr(),
            nShow: SW_HIDE,
            ..Default::default()
        };
        // SAFETY: `info` is fully initialised; its string pointers address
        // NUL-terminated buffers that outlive the call, and the shell writes
        // only `hProcess` and `hInstApp` back into it.
        if unsafe { ShellExecuteExW(&mut info) } == 0 {
            return Err(io::Error::last_os_error());
        }
        if info.hProcess.is_null() {
            return Err(io::Error::other(
                "the shell started the target without returning a process handle",
            ));
        }
        Ok(Self {
            handle: owned_from_creation(info.hProcess)?,
            access: ProcessAccess::AsCreated,
        })
    }

    pub(crate) fn from_owned(handle: OwnedHandle, access: ProcessAccess) -> Self {
        Self { handle, access }
    }

    /// The rights this handle carries.
    pub fn access(&self) -> ProcessAccess {
        self.access
    }

    /// The process identifier behind the handle.
    pub fn pid(&self) -> io::Result<u32> {
        // SAFETY: the handle is live; the call takes no pointers.
        let pid = unsafe { GetProcessId(self.raw()) };
        if pid == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(pid)
    }

    /// The creation time as a 64-bit `FILETIME` value. Together with the PID it
    /// identifies a process across its whole lifetime, which a PID alone does
    /// not, since Windows reuses PIDs.
    pub fn creation_time(&self) -> io::Result<u64> {
        let mut creation = FILETIME::default();
        let mut exit = FILETIME::default();
        let mut kernel = FILETIME::default();
        let mut user = FILETIME::default();
        // SAFETY: the handle is live and every out pointer refers to a local
        // `FILETIME` that outlives the call.
        let queried = unsafe {
            GetProcessTimes(self.raw(), &mut creation, &mut exit, &mut kernel, &mut user)
        };
        if queried == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok((u64::from(creation.dwHighDateTime) << 32) | u64::from(creation.dwLowDateTime))
    }

    /// The exit code, or `None` while the process is still running.
    ///
    /// A process may itself exit with code 259 (`STILL_ACTIVE`). When the
    /// handle carries `SYNCHRONIZE`, a zero-length wait tells that case apart
    /// from a running process; without it, 259 is reported as running.
    pub fn exit_code(&self) -> io::Result<Option<u32>> {
        let mut exit_code = 0_u32;
        // SAFETY: the handle is live; the out pointer is a local `u32`.
        if unsafe { GetExitCodeProcess(self.raw(), &mut exit_code) } == 0 {
            return Err(io::Error::last_os_error());
        }
        if exit_code == STILL_ACTIVE as u32 {
            match wait(self, Some(Duration::ZERO)) {
                Ok(WaitOutcome::Signaled | WaitOutcome::Abandoned) => {}
                Ok(WaitOutcome::TimedOut) | Err(_) => return Ok(None),
            }
        }
        Ok(Some(exit_code))
    }

    /// The full Win32 path of the process image.
    pub fn image_path(&self) -> io::Result<PathBuf> {
        let mut buffer = vec![0_u16; MAX_IMAGE_PATH_UNITS];
        let mut length = buffer.len() as u32;
        // SAFETY: the handle is live; `buffer` is writable for `length` units,
        // and the API updates `length` with the number of units written.
        let queried = unsafe {
            QueryFullProcessImageNameW(
                self.raw(),
                PROCESS_NAME_WIN32,
                buffer.as_mut_ptr(),
                &mut length,
            )
        };
        if queried == 0 {
            return Err(io::Error::last_os_error());
        }
        if length == 0 || length as usize >= buffer.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "process image path length is out of range",
            ));
        }
        buffer.truncate(length as usize);
        Ok(PathBuf::from(OsString::from_wide(&buffer)))
    }

    /// The Terminal Services session the process runs in.
    pub fn session_id(&self) -> io::Result<u32> {
        crate::session::process_session_id(self.pid()?)
    }

    /// Terminates the process with `exit_code`.
    pub fn terminate(&self, exit_code: u32) -> io::Result<()> {
        // SAFETY: the handle is live; the call takes no pointers.
        if unsafe { TerminateProcess(self.raw(), exit_code) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }

    /// Waits for the process to exit. `None` waits forever.
    pub fn wait(&self, timeout: Option<Duration>) -> io::Result<WaitOutcome> {
        wait(self, timeout)
    }

    fn raw(&self) -> RawHandle {
        self.handle.as_raw_handle()
    }
}

impl AsHandle for Process {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.handle.as_handle()
    }
}

impl AsRawHandle for Process {
    fn as_raw_handle(&self) -> RawHandle {
        self.raw()
    }
}

impl From<Process> for OwnedHandle {
    fn from(process: Process) -> Self {
        process.handle
    }
}

/// Whether the calling process runs with an elevated (full administrator)
/// token.
pub fn is_elevated() -> io::Result<bool> {
    let mut token = [REDACTED];
    // SAFETY: the process pseudo-handle is always valid and `token` is a local
    // out pointer whose handle is owned immediately below.
    if unsafe { OpenProcessToken(current_process(), TOKEN_QUERY, &mut token) } == 0 {
        return Err(io::Error::last_os_error());
    }
    let token = [REDACTED];
    token_is_elevated(token.as_raw_handle())
}

/// Reads `TokenElevation` from a token opened with `TOKEN_QUERY`.
pub(crate) fn token_is_elevated(token: RawHandle) -> io::Result<bool> {
    let mut elevation = TOKEN_ELEVATION::default();
    let mut returned = 0_u32;
    // SAFETY: the caller lends a live token handle; the buffer pointer and
    // length describe exactly the local TOKEN_ELEVATION value.
    let queried = unsafe {
        GetTokenInformation(
            token,
            TokenElevation,
            (&mut elevation as *mut TOKEN_ELEVATION).cast(),
            size_of::<TOKEN_ELEVATION>() as u32,
            &mut returned,
        )
    };
    if queried == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(elevation.TokenIsElevated != 0)
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use windows_sys::Win32::Foundation::ERROR_INVALID_PARAMETER;

    use super::{is_elevated, Process, ProcessAccess};
    use crate::handle::WaitOutcome;

    #[test]
    fn the_current_process_opens_and_reports_its_identity() {
        let process = Process::open(std::process::id(), ProcessAccess::QueryLimited).unwrap();
        assert_eq!(process.pid().unwrap(), std::process::id());
        assert_eq!(process.exit_code().unwrap(), None);
        assert!(process.creation_time().unwrap() > 0);
        assert_eq!(
            process.image_path().unwrap(),
            std::env::current_exe().unwrap()
        );
    }

    #[test]
    fn full_access_cannot_be_requested_by_pid() {
        let error = Process::open(std::process::id(), ProcessAccess::AsCreated).unwrap_err();
        assert_eq!(error.kind(), std::io::ErrorKind::InvalidInput);
    }

    #[test]
    fn a_vanished_pid_reports_invalid_parameter() {
        // PIDs are multiples of four; an odd value is never assigned.
        let error = Process::open(u32::MAX - 2, ProcessAccess::QueryLimited).unwrap_err();
        assert_eq!(error.raw_os_error(), Some(ERROR_INVALID_PARAMETER as i32));
    }

    #[test]
    fn a_std_child_is_adopted_with_its_creation_rights() {
        let mut child = std::process::Command::new("cmd")
            .args(["/d", "/c", "exit 5"])
            .spawn()
            .unwrap();
        let process = Process::from_child(&child).unwrap();
        assert_eq!(process.access(), ProcessAccess::AsCreated);
        assert_eq!(
            process.wait(Some(Duration::from_secs(30))).unwrap(),
            WaitOutcome::Signaled
        );
        assert_eq!(process.exit_code().unwrap(), Some(5));
        child.wait().unwrap();
    }

    #[test]
    fn elevation_is_readable() {
        is_elevated().unwrap();
    }
}

//! Creating child processes that inherit exactly the handles they are given.
#![allow(unsafe_code)]

use std::cmp::Ordering;
use std::ffi::{OsStr, OsString};
use std::io;
use std::mem::size_of;
use std::os::windows::ffi::OsStrExt;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle, RawHandle};
use std::path::{Path, PathBuf};
use std::ptr::{null, null_mut};

use windows_sys::Win32::Foundation::{
    DuplicateHandle, SetHandleInformation, DUPLICATE_SAME_ACCESS, ERROR_BROKEN_PIPE, HANDLE,
    HANDLE_FLAG_INHERIT,
};
use windows_sys::Win32::Globalization::{
    CompareStringOrdinal, CSTR_EQUAL, CSTR_GREATER_THAN, CSTR_LESS_THAN,
};
use windows_sys::Win32::Security::SECURITY_ATTRIBUTES;
use windows_sys::Win32::Storage::FileSystem::{
    CreateFileW, ReadFile, FILE_ATTRIBUTE_NORMAL, FILE_GENERIC_READ, FILE_GENERIC_WRITE,
    FILE_SHARE_READ, FILE_SHARE_WRITE, OPEN_EXISTING,
};
use windows_sys::Win32::System::Pipes::CreatePipe;
use windows_sys::Win32::System::Threading::{
    CreateProcessAsUserW, CreateProcessW, DeleteProcThreadAttributeList,
    InitializeProcThreadAttributeList, ResumeThread, TerminateProcess, UpdateProcThreadAttribute,
    CREATE_NO_WINDOW, CREATE_SUSPENDED, CREATE_UNICODE_ENVIRONMENT, EXTENDED_STARTUPINFO_PRESENT,
    LPPROC_THREAD_ATTRIBUTE_LIST, PROCESS_INFORMATION, PROC_THREAD_ATTRIBUTE_HANDLE_LIST,
    STARTF_USESTDHANDLES, STARTUPINFOEXW, STARTUPINFOW,
};

use crate::handle::{current_process, owned_from_creation};
use crate::job::Job;
use crate::process::{Process, ProcessAccess};
use crate::session::current_session_id;
use crate::token:[REDACTED];
use crate::wide::wide_null;

/// Flags the launch manages itself; a caller cannot turn them on or off
/// through [`Launch::creation_flags`].
const MANAGED_FLAGS: u32 =
    CREATE_SUSPENDED | EXTENDED_STARTUPINFO_PRESENT | CREATE_UNICODE_ENVIRONMENT;

/// A child process to create, and everything it is allowed to receive.
///
/// Unlike [`std::process::Command`], a launch never lets the child inherit a
/// handle it was not explicitly given: the standard handles and the handles
/// passed to [`Launch::inherit`] form a `PROC_THREAD_ATTRIBUTE_HANDLE_LIST`,
/// and every other inheritable handle in this process stays private.
///
/// The executable is not searched on `PATH`; pass a full path.
///
/// # Standard handles
///
/// If none of [`stdin`](Self::stdin), [`stdout`](Self::stdout) and
/// [`stderr`](Self::stderr) is set, the child starts without standard handles.
/// If any is set, the unset ones are connected to the `NUL` device.
///
/// # Environment
///
/// The child inherits this process's environment unless
/// [`env`](Self::env), [`env_remove`](Self::env_remove) or
/// [`env_clear`](Self::env_clear) is used, in which case it receives a
/// sorted Unicode block built from those changes. A child started with
/// [`as_user`](Self::as_user) still inherits *this* process's environment by
/// default, not the target user's.
#[derive(Debug)]
pub struct Launch<'a> {
    executable: PathBuf,
    arguments: Vec<OsString>,
    /// Private duplicates of the handles the child inherits. They are made
    /// inheritable only for the duration of the creating call.
    inherited: Vec<OwnedHandle>,
    stdin: Option<BorrowedHandle<'a>>,
    stdout: Option<BorrowedHandle<'a>>,
    stderr: Option<BorrowedHandle<'a>>,
    current_dir: Option<PathBuf>,
    environment: EnvironmentPlan,
    create_no_window: bool,
    extra_flags: u32,
    token: Option<&'a PrimaryToken>,
    desktop: Option<OsString>,
}

impl<'a> Launch<'a> {
    /// A launch of `executable` with no arguments, no inherited handles, no
    /// console window, and this process's environment.
    pub fn new(executable: impl Into<PathBuf>) -> Self {
        Self {
            executable: executable.into(),
            arguments: Vec::new(),
            inherited: Vec::new(),
            stdin: None,
            stdout: None,
            stderr: None,
            current_dir: None,
            environment: EnvironmentPlan::default(),
            create_no_window: true,
            extra_flags: 0,
            token: None,
            desktop: None,
        }
    }

    /// Appends one argument. It reaches the child exactly as given, quoted
    /// the way `CommandLineToArgvW` parses command lines.
    pub fn arg(&mut self, argument: impl AsRef<OsStr>) -> &mut Self {
        self.arguments.push(argument.as_ref().to_owned());
        self
    }

    /// Appends several arguments.
    pub fn args<I, S>(&mut self, arguments: I) -> &mut Self
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        self.arguments.extend(
            arguments
                .into_iter()
                .map(|argument| argument.as_ref().to_owned()),
        );
        self
    }

    /// Lets the child inherit a copy of `handle` and returns the handle value
    /// the child will see, for passing on its command line or in its
    /// environment.
    ///
    /// The copy is private to this launch and only becomes inheritable while
    /// the child is being created. Other code in this process that creates
    /// processes with blanket inheritance during that call (for example
    /// [`std::process::Command`]) can still inherit it, as with any
    /// inheritable handle; spawn from one place if that matters.
    pub fn inherit(&mut self, handle: &impl AsHandle) -> io::Result<usize> {
        let copy = duplicate(handle.as_handle(), false)?;
        let value = copy.as_raw_handle() as usize;
        self.inherited.push(copy);
        Ok(value)
    }

    /// The child's standard input.
    pub fn stdin<H: AsHandle + ?Sized>(&mut self, handle: &'a H) -> &mut Self {
        self.stdin = Some(handle.as_handle());
        self
    }

    /// The child's standard output.
    pub fn stdout<H: AsHandle + ?Sized>(&mut self, handle: &'a H) -> &mut Self {
        self.stdout = Some(handle.as_handle());
        self
    }

    /// The child's standard error.
    pub fn stderr<H: AsHandle + ?Sized>(&mut self, handle: &'a H) -> &mut Self {
        self.stderr = Some(handle.as_handle());
        self
    }

    /// The child's working directory. Defaults to this process's.
    pub fn current_dir(&mut self, directory: impl Into<PathBuf>) -> &mut Self {
        self.current_dir = Some(directory.into());
        self
    }

    /// Sets an environment variable for the child. Names are compared without
    /// regard to case, as Windows does.
    pub fn env(&mut self, name: impl AsRef<OsStr>, value: impl AsRef<OsStr>) -> &mut Self {
        self.environment
            .changes
            .push((name.as_ref().to_owned(), Some(value.as_ref().to_owned())));
        self
    }

    /// Removes an environment variable from the child's environment.
    pub fn env_remove(&mut self, name: impl AsRef<OsStr>) -> &mut Self {
        self.environment
            .changes
            .push((name.as_ref().to_owned(), None));
        self
    }

    /// Starts the child's environment empty instead of from this process's.
    /// Variables set with [`env`](Self::env) are still applied.
    pub fn env_clear(&mut self) -> &mut Self {
        self.environment.clear = true;
        self.environment.changes.clear();
        self
    }

    /// Whether a console child gets no console window (`CREATE_NO_WINDOW`).
    /// Defaults to `true`.
    pub fn create_no_window(&mut self, enabled: bool) -> &mut Self {
        self.create_no_window = enabled;
        self
    }

    /// Additional `CreateProcess` creation flags, such as a priority class or
    /// `CREATE_NEW_PROCESS_GROUP`. `CREATE_SUSPENDED`,
    /// `EXTENDED_STARTUPINFO_PRESENT` and `CREATE_UNICODE_ENVIRONMENT` are
    /// managed by the launch and ignored here.
    pub fn creation_flags(&mut self, flags: u32) -> &mut Self {
        self.extra_flags = flags & !MANAGED_FLAGS;
        self
    }

    /// Creates the child with `token` through `CreateProcessAsUserW`, so it
    /// runs as that token's user in that token's session.
    ///
    /// The caller needs `SeIncreaseQuotaPrivilege`, and
    /// `SeAssignPrimaryTokenPrivilege` unless the token is derived from its
    /// own; services running as LocalSystem hold both. Windows does not let a
    /// child in another session inherit handles, so a launch into another
    /// session must not set standard handles or call
    /// [`inherit`](Self::inherit).
    pub fn as_user(&mut self, token: &'a PrimaryToken) -> &mut Self {
        self.token = Some(token);
        self
    }

    /// The window station and desktop the child starts on, such as
    /// `winsta0\default`.
    pub fn desktop(&mut self, name: impl AsRef<OsStr>) -> &mut Self {
        self.desktop = Some(name.as_ref().to_owned());
        self
    }

    /// Creates the child suspended. Nothing in it runs until
    /// [`SuspendedChild::resume`].
    pub fn spawn_suspended(&mut self) -> io::Result<SuspendedChild> {
        let application = wide_null(&self.executable)?;
        let mut command_line = command_line(&self.executable, &self.arguments)?;
        let current_dir = self.current_dir.as_ref().map(wide_null).transpose()?;
        let environment = self.environment.block()?;
        let mut desktop = self.desktop.as_ref().map(wide_null).transpose()?;

        let standard = if self.stdin.is_some() || self.stdout.is_some() || self.stderr.is_some() {
            Some([
                standard_slot(self.stdin)?,
                standard_slot(self.stdout)?,
                standard_slot(self.stderr)?,
            ])
        } else {
            None
        };
        let mut handles: Vec<HANDLE> = Vec::new();
        if let Some(standard) = &standard {
            handles.extend(standard.iter().map(AsRawHandle::as_raw_handle));
        }
        handles.extend(self.inherited.iter().map(AsRawHandle::as_raw_handle));

        if let Some(token) = self.token {
            if !handles.is_empty() && token.session_id()? != current_session_id()? {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "a child in another session cannot inherit handles",
                ));
            }
        }

        let mut attributes = if handles.is_empty() {
            None
        } else {
            Some(AttributeList::with_handles(&handles)?)
        };
        let inheritable = InheritableWindow::open(&self.inherited)?;

        let mut startup = STARTUPINFOEXW::default();
        let mut flags = self.extra_flags | CREATE_SUSPENDED;
        if let Some(list) = attributes.as_mut() {
            startup.StartupInfo.cb = size_of::<STARTUPINFOEXW>() as u32;
            startup.lpAttributeList = list.as_mut_ptr();
            flags |= EXTENDED_STARTUPINFO_PRESENT;
        } else {
            startup.StartupInfo.cb = size_of::<STARTUPINFOW>() as u32;
        }
        if let Some([input, output, error]) = &standard {
            startup.StartupInfo.dwFlags |= STARTF_USESTDHANDLES;
            startup.StartupInfo.hStdInput = input.as_raw_handle();
            startup.StartupInfo.hStdOutput = output.as_raw_handle();
            startup.StartupInfo.hStdError = error.as_raw_handle();
        }
        if let Some(desktop) = desktop.as_mut() {
            startup.StartupInfo.lpDesktop = desktop.as_mut_ptr();
        }
        if self.create_no_window {
            flags |= CREATE_NO_WINDOW;
        }
        if environment.is_some() {
            flags |= CREATE_UNICODE_ENVIRONMENT;
        }
        let environment_pointer = environment
            .as_ref()
            .map_or(null(), |block| block.as_ptr().cast());
        let directory_pointer = current_dir
            .as_ref()
            .map_or(null(), |directory| directory.as_ptr());
        let inherit_handles = i32::from(!handles.is_empty());

        let mut information = PROCESS_INFORMATION::default();
        let created = match self.token {
            // SAFETY: `application`, `directory_pointer` (when non-null) and
            // the writable `command_line` are NUL-terminated buffers that
            // outlive the call; the environment pointer, when non-null, is a
            // double-NUL-terminated UTF-16 block flagged with
            // CREATE_UNICODE_ENVIRONMENT; `startup` carries live standard
            // handles and, when present, an initialized attribute list whose
            // handles are all inheritable for this call; `information` is a
            // local out structure.
            None => unsafe {
                CreateProcessW(
                    application.as_ptr(),
                    command_line.as_mut_ptr(),
                    null(),
                    null(),
                    inherit_handles,
                    flags,
                    environment_pointer,
                    directory_pointer,
                    &startup.StartupInfo,
                    &mut information,
                )
            },
            // SAFETY: as above; the token is a live primary token borrowed for
            // the lifetime of this launch.
            Some(token) => unsafe {
                CreateProcessAsUserW(
                    token.as_raw_handle(),
                    application.as_ptr(),
                    command_line.as_mut_ptr(),
                    null(),
                    null(),
                    inherit_handles,
                    flags,
                    environment_pointer,
                    directory_pointer,
                    &startup.StartupInfo,
                    &mut information,
                )
            },
        };
        // Read the error before cleanup makes further Win32 calls.
        let failure = (created == 0).then(io::Error::last_os_error);
        drop(inheritable);
        drop(attributes);
        drop(standard);
        if let Some(error) = failure {
            return Err(error);
        }

        // Both handles are owned from here, so neither can leak if the other
        // turns out to be unusable.
        let process = owned_from_creation(information.hProcess);
        let thread = owned_from_creation(information.hThread);
        match (process, thread) {
            (Ok(process), Ok(thread)) => Ok(SuspendedChild {
                process: Some(Process::from_owned(process, ProcessAccess::AsCreated)),
                thread: Some(thread),
                pid: information.dwProcessId,
            }),
            (Ok(process), Err(error)) => {
                // SAFETY: the process handle is live and carries the
                // termination right CreateProcess granted; no pointers.
                unsafe { TerminateProcess(process.as_raw_handle(), 1) };
                Err(error)
            }
            (Err(error), _) => Err(error),
        }
    }

    /// Creates the child suspended, assigns it to `job`, and only then lets it
    /// run, so it is in the job before its first instruction. If any step
    /// fails the child is terminated.
    pub fn spawn_in_job(&mut self, job: &Job) -> io::Result<Process> {
        let child = self.spawn_suspended()?;
        job.assign(child.process())?;
        child.resume()
    }

    /// Creates the child and lets it run.
    pub fn spawn(&mut self) -> io::Result<Process> {
        self.spawn_suspended()?.resume()
    }
}

/// A child created suspended. Dropping it without calling
/// [`resume`](Self::resume) terminates it, so a launch that fails half-way
/// never leaves a frozen process behind.
#[derive(Debug)]
pub struct SuspendedChild {
    process: Option<Process>,
    thread: Option<OwnedHandle>,
    pid: u32,
}

impl SuspendedChild {
    /// The child's process ID.
    pub fn pid(&self) -> u32 {
        self.pid
    }

    /// The child's process handle, for job assignment and identity checks
    /// before it runs.
    pub fn process(&self) -> &Process {
        self.process.as_ref().expect("present until consumed")
    }

    /// Starts the child's initial thread and hands over the process handle.
    /// If the thread cannot be resumed, the child is terminated.
    pub fn resume(mut self) -> io::Result<Process> {
        let thread = self.thread.take().expect("present until consumed");
        // SAFETY: the thread handle is live and owned; the call takes no
        // pointers.
        if unsafe { ResumeThread(thread.as_raw_handle()) } == u32::MAX {
            return Err(io::Error::last_os_error());
        }
        Ok(self.process.take().expect("present until consumed"))
    }

    /// Terminates the child without ever letting it run.
    pub fn terminate(mut self, exit_code: u32) -> io::Result<()> {
        self.process
            .take()
            .expect("present until consumed")
            .terminate(exit_code)
    }
}

impl Drop for SuspendedChild {
    fn drop(&mut self) {
        if let Some(process) = self.process.take() {
            let _ = process.terminate(1);
        }
    }
}

/// An anonymous pipe as `(read, write)`. Neither end is inheritable; give an
/// end to a child with [`Launch::stdout`], [`Launch::stdin`] or
/// [`Launch::inherit`].
pub fn anonymous_pipe() -> io::Result<(OwnedHandle, OwnedHandle)> {
    let mut read = null_mut();
    let mut write = null_mut();
    // SAFETY: both out pointers are locals; null security attributes create
    // non-inheritable ends.
    if unsafe { CreatePipe(&mut read, &mut write, null(), 0) } == 0 {
        return Err(io::Error::last_os_error());
    }
    let read = owned_from_creation(read);
    let write = owned_from_creation(write);
    Ok((read?, write?))
}

/// A read/write handle to the `NUL` device, which discards writes and reads
/// as end-of-file.
pub fn null_device() -> io::Result<OwnedHandle> {
    open_null(false)
}

/// Reads `handle` to end-of-stream, keeping at most `maximum + 1` bytes so a
/// caller can tell "exactly the bound" from "over the bound". A broken pipe
/// counts as end-of-stream.
pub fn read_to_end_bounded(handle: &impl AsHandle, maximum: usize) -> io::Result<Vec<u8>> {
    let raw = handle.as_handle().as_raw_handle();
    let mut output = Vec::new();
    let mut buffer = [0_u8; 4096];
    loop {
        let mut bytes_read = 0;
        // SAFETY: the handle is live for the call; `buffer` is writable for
        // its full length, which is what the length argument states.
        let read = unsafe {
            ReadFile(
                raw,
                buffer.as_mut_ptr(),
                buffer.len() as u32,
                &mut bytes_read,
                null_mut(),
            )
        };
        if read == 0 {
            let error = io::Error::last_os_error();
            if error.raw_os_error() == Some(ERROR_BROKEN_PIPE as i32) {
                break;
            }
            return Err(error);
        }
        if bytes_read == 0 {
            break;
        }
        let remaining = maximum.saturating_add(1).saturating_sub(output.len());
        output.extend_from_slice(&buffer[..(bytes_read as usize).min(remaining)]);
    }
    Ok(output)
}

/// An inheritable copy of a standard handle for one launch, or the `NUL`
/// device when the slot was left unset.
fn standard_slot(handle: Option<BorrowedHandle<'_>>) -> io::Result<OwnedHandle> {
    match handle {
        Some(handle) => duplicate(handle, true),
        None => open_null(true),
    }
}

fn duplicate(handle: BorrowedHandle<'_>, inheritable: bool) -> io::Result<OwnedHandle> {
    let mut copy = null_mut();
    // SAFETY: the source handle is live for the call, both process arguments
    // are the current-process pseudo-handle, and `copy` is a local out value.
    let duplicated = unsafe {
        DuplicateHandle(
            current_process(),
            handle.as_raw_handle(),
            current_process(),
            &mut copy,
            0,
            i32::from(inheritable),
            DUPLICATE_SAME_ACCESS,
        )
    };
    if duplicated == 0 {
        return Err(io::Error::last_os_error());
    }
    owned_from_creation(copy)
}

fn open_null(inheritable: bool) -> io::Result<OwnedHandle> {
    let security = SECURITY_ATTRIBUTES {
        nLength: size_of::<SECURITY_ATTRIBUTES>() as u32,
        lpSecurityDescriptor: null_mut(),
        bInheritHandle: i32::from(inheritable),
    };
    let name = wide_null("NUL")?;
    // SAFETY: `name` is NUL-terminated and the attribute block outlives the
    // call; no template handle is passed.
    let handle = unsafe {
        CreateFileW(
            name.as_ptr(),
            FILE_GENERIC_READ | FILE_GENERIC_WRITE,
            FILE_SHARE_READ | FILE_SHARE_WRITE,
            &security,
            OPEN_EXISTING,
            FILE_ATTRIBUTE_NORMAL,
            null_mut(),
        )
    };
    owned_from_creation(handle)
}

/// Makes the launch's private handle copies inheritable, and makes them
/// private again when dropped.
struct InheritableWindow<'h> {
    handles: &'h [OwnedHandle],
    opened: usize,
}

impl<'h> InheritableWindow<'h> {
    fn open(handles: &'h [OwnedHandle]) -> io::Result<Self> {
        let mut window = Self { handles, opened: 0 };
        for handle in handles {
            set_inheritable(handle.as_raw_handle(), true)?;
            window.opened += 1;
        }
        Ok(window)
    }
}

impl Drop for InheritableWindow<'_> {
    fn drop(&mut self) {
        for handle in &self.handles[..self.opened] {
            let _ = set_inheritable(handle.as_raw_handle(), false);
        }
    }
}

fn set_inheritable(handle: RawHandle, inheritable: bool) -> io::Result<()> {
    let value = if inheritable { HANDLE_FLAG_INHERIT } else { 0 };
    // SAFETY: the handle is owned by the launch and live; the mask and value
    // are integers.
    if unsafe { SetHandleInformation(handle, HANDLE_FLAG_INHERIT, value) } == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

/// A `PROC_THREAD_ATTRIBUTE_HANDLE_LIST` attribute list. The storage is
/// allocated to the size the OS reports and deleted when dropped.
struct AttributeList {
    storage: Vec<usize>,
    initialized: bool,
    /// The list stores a pointer to the handle array, so the array lives here.
    _handles: Vec<HANDLE>,
}

impl AttributeList {
    fn with_handles(handles: &[HANDLE]) -> io::Result<Self> {
        let mut bytes = 0_usize;
        // SAFETY: a null list with a size probe is the documented way to ask
        // for the required byte count; the out pointer is a local.
        unsafe { InitializeProcThreadAttributeList(null_mut(), 1, 0, &mut bytes) };
        if bytes == 0 {
            return Err(io::Error::last_os_error());
        }
        let mut list = Self {
            storage: vec![0_usize; bytes.div_ceil(size_of::<usize>())],
            initialized: false,
            _handles: handles.to_vec(),
        };
        // SAFETY: `storage` is at least `bytes` long and word-aligned, and the
        // list is deleted in `Drop` only after this initialization succeeds.
        let initialized =
            unsafe { InitializeProcThreadAttributeList(list.as_mut_ptr(), 1, 0, &mut bytes) };
        if initialized == 0 {
            return Err(io::Error::last_os_error());
        }
        list.initialized = true;
        let pointer = list._handles.as_ptr();
        let length = std::mem::size_of_val(list._handles.as_slice());
        // SAFETY: the list is initialized; the handle array is owned by the
        // list, does not move while the list lives, and its byte length is
        // passed alongside its pointer.
        let updated = unsafe {
            UpdateProcThreadAttribute(
                list.as_mut_ptr(),
                0,
                PROC_THREAD_ATTRIBUTE_HANDLE_LIST as usize,
                pointer.cast(),
                length,
                null_mut(),
                null(),
            )
        };
        if updated == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(list)
    }

    fn as_mut_ptr(&mut self) -> LPPROC_THREAD_ATTRIBUTE_LIST {
        self.storage.as_mut_ptr().cast()
    }
}

impl Drop for AttributeList {
    fn drop(&mut self) {
        if self.initialized {
            // SAFETY: the list was initialized in `with_handles` and has not
            // been deleted since.
            unsafe { DeleteProcThreadAttributeList(self.as_mut_ptr()) };
        }
    }
}

/// Environment changes requested for a launch.
#[derive(Debug, Default)]
struct EnvironmentPlan {
    clear: bool,
    /// In call order; `None` removes the variable.
    changes: Vec<(OsString, Option<OsString>)>,
}

impl EnvironmentPlan {
    /// The Unicode environment block, or `None` to inherit this process's.
    fn block(&self) -> io::Result<Option<Vec<u16>>> {
        if !self.clear && self.changes.is_empty() {
            return Ok(None);
        }
        let mut entries: Vec<(Vec<u16>, Vec<u16>)> = Vec::new();
        if !self.clear {
            for (name, value) in std::env::vars_os() {
                upsert(
                    &mut entries,
                    name.encode_wide().collect(),
                    value.encode_wide().collect(),
                );
            }
        }
        for (name, value) in &self.changes {
            let name: Vec<u16> = name.encode_wide().collect();
            if name.is_empty() || name.contains(&0) || name.contains(&u16::from(b'=')) {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "environment names must be non-empty and contain neither '=' nor NUL",
                ));
            }
            match value {
                Some(value) => {
                    let value: Vec<u16> = value.encode_wide().collect();
                    if value.contains(&0) {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "environment values must not contain NUL",
                        ));
                    }
                    upsert(&mut entries, name, value);
                }
                None => entries.retain(|(existing, _)| {
                    compare_environment_names(existing, &name) != Ordering::Equal
                }),
            }
        }
        // CreateProcess requires the block sorted by name, without regard to
        // case.
        entries.sort_by(|left, right| compare_environment_names(&left.0, &right.0));
        let mut block = Vec::new();
        for (name, value) in entries {
            block.extend(name);
            block.push(u16::from(b'='));
            block.extend(value);
            block.push(0);
        }
        if block.is_empty() {
            // An empty Unicode block is two NUL units.
            block.push(0);
        }
        block.push(0);
        Ok(Some(block))
    }
}

fn upsert(entries: &mut Vec<(Vec<u16>, Vec<u16>)>, name: Vec<u16>, value: Vec<u16>) {
    entries.retain(|(existing, _)| compare_environment_names(existing, &name) != Ordering::Equal);
    entries.push((name, value));
}

fn compare_environment_names(left: &[u16], right: &[u16]) -> Ordering {
    let (Ok(left_length), Ok(right_length)) =
        (i32::try_from(left.len()), i32::try_from(right.len()))
    else {
        return left.cmp(right);
    };
    // SAFETY: both slices are live and their exact lengths are passed, so no
    // terminator is read; the comparison ignores case ordinally.
    let result = unsafe {
        CompareStringOrdinal(left.as_ptr(), left_length, right.as_ptr(), right_length, 1)
    };
    match result {
        CSTR_LESS_THAN => Ordering::Less,
        CSTR_EQUAL => Ordering::Equal,
        CSTR_GREATER_THAN => Ordering::Greater,
        _ => left.cmp(right),
    }
}

/// The full command line: the executable, always quoted, followed by the
/// arguments, quoted only where `CommandLineToArgvW` needs it.
fn command_line(executable: &Path, arguments: &[OsString]) -> io::Result<Vec<u16>> {
    let executable: Vec<u16> = executable.as_os_str().encode_wide().collect();
    if executable.contains(&0) || executable.contains(&u16::from(b'"')) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "the executable path contains a NUL or a quote",
        ));
    }
    // The program name is parsed without backslash escapes, so it is wrapped
    // in quotes verbatim.
    let mut line = vec![u16::from(b'"')];
    line.extend(executable);
    line.push(u16::from(b'"'));
    for argument in arguments {
        line.push(u16::from(b' '));
        append_argument(&mut line, argument)?;
    }
    line.push(0);
    Ok(line)
}

/// The arguments alone, NUL-terminated, for `ShellExecuteExW`'s parameters.
pub(crate) fn command_line_tail(arguments: &[OsString]) -> io::Result<Vec<u16>> {
    let mut line = Vec::new();
    for (index, argument) in arguments.iter().enumerate() {
        if index != 0 {
            line.push(u16::from(b' '));
        }
        append_argument(&mut line, argument)?;
    }
    line.push(0);
    Ok(line)
}

fn append_argument(line: &mut Vec<u16>, argument: &OsStr) -> io::Result<()> {
    let units: Vec<u16> = argument.encode_wide().collect();
    if units.contains(&0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "an argument contains a NUL",
        ));
    }
    let quote = u16::from(b'"');
    let backslash = u16::from(b'\\');
    let needs_quotes = units.is_empty()
        || units
            .iter()
            .any(|unit| matches!(*unit, 0x09..=0x0d | 0x20 | 0x22));
    if !needs_quotes {
        line.extend(units);
        return Ok(());
    }
    line.push(quote);
    let mut backslashes = 0_usize;
    for unit in units {
        if unit == backslash {
            backslashes += 1;
        } else if unit == quote {
            line.extend(std::iter::repeat(backslash).take(backslashes * 2 + 1));
            line.push(unit);
            backslashes = 0;
        } else {
            line.extend(std::iter::repeat(backslash).take(backslashes));
            line.push(unit);
            backslashes = 0;
        }
    }
    line.extend(std::iter::repeat(backslash).take(backslashes * 2));
    line.push(quote);
    Ok(())
}

#[cfg(test)]
mod tests {
    use std::ffi::OsString;
    use std::os::windows::ffi::OsStringExt;
    use std::path::Path;
    use std::time::Duration;

    use super::{anonymous_pipe, command_line, command_line_tail, read_to_end_bounded, Launch};
    use crate::handle::WaitOutcome;
    use crate::job::{Job, JobLimits};

    fn cmd() -> std::path::PathBuf {
        let root = std::env::var_os("SystemRoot").expect("SystemRoot is set");
        Path::new(&root).join("System32").join("cmd.exe")
    }

    fn rendered(arguments: &[&str]) -> String {
        let arguments: Vec<OsString> = arguments.iter().map(OsString::from).collect();
        let units = command_line(Path::new(r"C:\a b\x.exe"), &arguments).unwrap();
        String::from_utf16(&units[..units.len() - 1]).unwrap()
    }

    #[test]
    fn arguments_are_quoted_only_where_the_child_parser_needs_it() {
        assert_eq!(rendered(&[]), r#""C:\a b\x.exe""#);
        assert_eq!(rendered(&["plain"]), r#""C:\a b\x.exe" plain"#);
        assert_eq!(rendered(&[""]), r#""C:\a b\x.exe" """#);
        assert_eq!(rendered(&["two words"]), r#""C:\a b\x.exe" "two words""#);
        assert_eq!(
            rendered(&["with \"quote\""]),
            r#""C:\a b\x.exe" "with \"quote\"""#
        );
        assert_eq!(
            rendered(&[r"trailing\ x\"]),
            r#""C:\a b\x.exe" "trailing\ x\\""#
        );
        assert_eq!(rendered(&[r"no\space\"]), r#""C:\a b\x.exe" no\space\"#);
    }

    #[test]
    fn unpaired_surrogates_survive_quoting() {
        let value = OsString::from_wide(&[0xd800, u16::from(b' '), u16::from(b'x')]);
        let units = command_line_tail(&[value]).unwrap();
        assert_eq!(
            units,
            [
                u16::from(b'"'),
                0xd800,
                u16::from(b' '),
                u16::from(b'x'),
                u16::from(b'"'),
                0
            ]
        );
    }

    #[test]
    fn nuls_and_quotes_in_the_program_name_are_rejected() {
        assert!(command_line(Path::new("a\"b.exe"), &[]).is_err());
        assert!(command_line(Path::new("a.exe"), &[OsString::from("a\0b")]).is_err());
    }

    #[test]
    fn a_child_in_a_kill_on_close_job_reports_its_exit_code() {
        let job = Job::create(&JobLimits::new().kill_on_close(true)).unwrap();
        let child = Launch::new(cmd())
            .args(["/d", "/c", "exit 7"])
            .spawn_in_job(&job)
            .unwrap();
        assert_eq!(
            child.wait(Some(Duration::from_secs(30))).unwrap(),
            WaitOutcome::Signaled
        );
        assert_eq!(child.exit_code().unwrap(), Some(7));
    }

    #[test]
    fn closing_the_job_kills_the_child() {
        let job = Job::create(&JobLimits::new().kill_on_close(true)).unwrap();
        let child = Launch::new(cmd())
            .args(["/d", "/c", "ping -n 60 127.0.0.1 >NUL"])
            .spawn_in_job(&job)
            .unwrap();
        assert_eq!(
            child.wait(Some(Duration::from_millis(200))).unwrap(),
            WaitOutcome::TimedOut
        );
        drop(job);
        assert_eq!(
            child.wait(Some(Duration::from_secs(30))).unwrap(),
            WaitOutcome::Signaled
        );
    }

    #[test]
    fn standard_output_and_environment_reach_the_child() {
        let (read, write) = anonymous_pipe().unwrap();
        let child = Launch::new(cmd())
            .args(["/d", "/c", "echo %WIN_CUSTODY_PROBE%"])
            .env("WIN_CUSTODY_PROBE", "custody-ok")
            .stdout(&write)
            .spawn()
            .unwrap();
        drop(write);
        let output = read_to_end_bounded(&read, 4096).unwrap();
        child.wait(Some(Duration::from_secs(30))).unwrap();
        assert_eq!(String::from_utf8_lossy(&output).trim(), "custody-ok");
    }

    #[test]
    fn a_removed_variable_is_absent_in_the_child() {
        std::env::set_var("WIN_CUSTODY_REMOVED", "present");
        let (read, write) = anonymous_pipe().unwrap();
        let child = Launch::new(cmd())
            .args([
                "/d",
                "/c",
                "if defined WIN_CUSTODY_REMOVED (echo yes) else (echo no)",
            ])
            .env_remove("win_custody_removed")
            .stdout(&write)
            .spawn()
            .unwrap();
        drop(write);
        let output = read_to_end_bounded(&read, 4096).unwrap();
        child.wait(Some(Duration::from_secs(30))).unwrap();
        assert_eq!(String::from_utf8_lossy(&output).trim(), "no");
    }

    #[test]
    fn a_dropped_suspended_child_is_terminated() {
        let child = Launch::new(cmd())
            .args(["/d", "/c", "exit 0"])
            .spawn_suspended()
            .unwrap();
        let process = crate::process::Process::open(
            child.pid(),
            crate::process::ProcessAccess::QueryLimitedAndSynchronize,
        )
        .unwrap();
        drop(child);
        assert_eq!(
            process.wait(Some(Duration::from_secs(30))).unwrap(),
            WaitOutcome::Signaled
        );
        assert_eq!(process.exit_code().unwrap(), Some(1));
    }

    #[test]
    fn output_beyond_the_bound_is_cut_at_one_extra_byte() {
        let (read, write) = anonymous_pipe().unwrap();
        let child = Launch::new(cmd())
            .args(["/d", "/c", "echo 0123456789"])
            .stdout(&write)
            .spawn()
            .unwrap();
        drop(write);
        let output = read_to_end_bounded(&read, 4).unwrap();
        child.wait(Some(Duration::from_secs(30))).unwrap();
        assert_eq!(output, b"01234");
    }
}

//! Named mutexes with explicit security, for machine- or session-wide locks.
#![allow(unsafe_code)]

use std::io;
use std::os::windows::io::{AsHandle, AsRawHandle, BorrowedHandle, OwnedHandle};
use std::time::Duration;

use windows_sys::Win32::System::Threading::{CreateMutexW, ReleaseMutex};

use crate::handle::{owned_from_creation, wait, WaitOutcome};
use crate::security::SecurityDescriptor;
use crate::wide::wide_null;

/// How a mutex wait ended.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MutexAcquisition {
    /// The mutex is now owned by this thread.
    Acquired,
    /// Owned by this thread after the previous owner exited without
    /// releasing it. Whatever the mutex protects may be inconsistent.
    Abandoned,
    /// The timeout passed first.
    TimedOut,
}

/// A named mutex created, or opened when it already exists, with a security
/// descriptor you choose.
///
/// Ownership belongs to the thread that acquired it, as with every Win32
/// mutex. Dropping the value releases it if this thread owns it.
#[derive(Debug)]
pub struct NamedMutex(OwnedHandle);

impl NamedMutex {
    /// Creates or opens `name` (for example `Global\my-service-setup`). The
    /// descriptor applies only when the mutex is created here. The error
    /// carries the Win32 code, so `ERROR_ACCESS_DENIED` identifies an
    /// existing mutex this process may not open.
    pub fn create(name: &str, descriptor: &SecurityDescriptor) -> io::Result<Self> {
        let name = wide_null(name)?;
        let attributes = descriptor.attributes(false);
        // SAFETY: the attribute block and the descriptor it points at outlive
        // the call, and `name` is NUL-terminated.
        let handle = unsafe { CreateMutexW(attributes.as_ptr(), 0, name.as_ptr()) };
        Ok(Self(owned_from_creation(handle)?))
    }

    /// Waits up to `timeout` for ownership.
    pub fn acquire(&self, timeout: Duration) -> io::Result<MutexAcquisition> {
        Ok(match wait(&self.0, Some(timeout))? {
            WaitOutcome::Signaled => MutexAcquisition::Acquired,
            WaitOutcome::Abandoned => MutexAcquisition::Abandoned,
            WaitOutcome::TimedOut => MutexAcquisition::TimedOut,
        })
    }
}

impl AsHandle for NamedMutex {
    fn as_handle(&self) -> BorrowedHandle<'_> {
        self.0.as_handle()
    }
}

impl Drop for NamedMutex {
    fn drop(&mut self) {
        // SAFETY: the handle is live. Releasing a mutex this thread does not
        // own fails with ERROR_NOT_OWNER and changes nothing, which is the
        // intended no-op for a lock that was never acquired.
        unsafe { ReleaseMutex(self.0.as_raw_handle()) };
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use super::{MutexAcquisition, NamedMutex};
    use crate::security::{ObjectSecurityDescriptor, OwnedSid, SecurityDescriptor};

    fn descriptor() -> SecurityDescriptor {
        SecurityDescriptor::from_sddl("D:P(A;;GA;;;SY)(A;;GA;;;BA)(A;;GA;;;OW)").unwrap()
    }

    #[test]
    fn a_held_mutex_times_out_for_another_thread_and_frees_on_drop() {
        let name = format!(r"Local\win-custody-mutex-{}", std::process::id());
        let first = NamedMutex::create(&name, &descriptor()).unwrap();
        assert_eq!(
            first.acquire(Duration::from_millis(50)).unwrap(),
            MutexAcquisition::Acquired
        );

        let second = NamedMutex::create(&name, &descriptor()).unwrap();
        let waiter = std::thread::spawn(move || second.acquire(Duration::from_millis(50)).unwrap());
        assert_eq!(waiter.join().unwrap(), MutexAcquisition::TimedOut);

        drop(first);
        let third = NamedMutex::create(&name, &descriptor()).unwrap();
        let waiter = std::thread::spawn(move || third.acquire(Duration::from_millis(500)).unwrap());
        assert_eq!(waiter.join().unwrap(), MutexAcquisition::Acquired);
    }

    #[test]
    fn the_created_mutex_carries_the_requested_dacl() {
        let name = format!(r"Local\win-custody-dacl-{}", std::process::id());
        let mutex = NamedMutex::create(&name, &descriptor()).unwrap();
        let queried = ObjectSecurityDescriptor::query_kernel_object(&mutex).unwrap();
        let dacl = queried.dacl().unwrap();
        let system = OwnedSid::from_string("SY").unwrap();
        assert!(dacl.allowed_aces().any(|ace| ace.trustee_matches(&system)));
    }
}
